import{E as b}from"./exportFormatSchemas-DHH-9d5C.js";import{b as j,e as P,C as h,A,F as S}from"./exportHelpGuide-BpVXNOke.js";import{L as l,a as w}from"./latvianAccountingSystems-DYmEHU5X.js";const m=["FH provides these destination choices, settings and instructions. Its current export downloads are data previews, not validated vendor import files; API delivery requires a connected server adapter. Do not import a preview as an official template or treat a saved setting as a successful transfer.","FH pateikia šiuos gavėjo pasirinkimus, nustatymus ir instrukcijas. Dabartiniai eksporto failai yra duomenų peržiūros, ne patikrinti tiekėjo importo failai; siuntimui per API reikia prijungtos serverio jungties. Peržiūros neimportuokite kaip oficialaus šablono, o išsaugoto nustatymo nelaikykite sėkmingu perdavimu."],n=(i,a,s)=>({title:i,system:a,steps:s}),I={"MONEO Excel":[n(["Purchase invoices: official workbook","Pirkimo sąskaitos: oficialus šablonas"],"MONEO",[["Download Pieg_Rekinu_Imp.xlsx from the official purchase-import article linked below. Enter the supplier identifier, invoice number/date, VAT, amounts and GL account in the template’s corresponding columns; complete its mandatory fields.","Iš žemiau pateikto oficialaus pirkimų importo straipsnio atsisiųskite Pieg_Rekinu_Imp.xlsx. Į atitinkamus šablono stulpelius įrašykite tiekėjo identifikatorių, numerį, datą, PVM, sumas ir DK sąskaitą; užpildykite privalomus laukus."],["Create supplier cards and the required GL accounts in MONEO beforehand. Supplier registration numbers must match. Check invoice numbers: repeated supplier-invoice numbers in one workbook can be combined.","MONEO iš anksto sukurkite tiekėjų korteles ir reikalingas DK sąskaitas. Tiekėjų registracijos numeriai turi sutapti. Patikrinkite numerius: viename faile pasikartojantys tiekėjo sąskaitų numeriai gali būti sujungti."],["Keep the original column order, column count and worksheets. Save as XLSX with no more than 200 rows per file; use separate files for a larger import.","Nekeiskite originalios stulpelių tvarkos, jų skaičiaus ir darbalapių. Išsaugokite XLSX, ne daugiau kaip 200 eilučių faile; didesnį importą padalykite į atskirus failus."],["Use the supplier-invoice import in the intended MONEO company and choose the completed workbook. Review the import result and open the created invoices before posting them.","Reikiamoje MONEO įmonėje rinkitės tiekėjų sąskaitų importą ir užpildytą failą. Patikrinkite rezultatą ir sukurtas sąskaitas prieš jas registruodami apskaitoje."]]),n(["Sales invoices: totals or lines","Pardavimo sąskaitos: sumos arba eilutės"],"MONEO",[["Download Rekinu_Imp_2024.xlsx from the official sales-import article. Use existing customer codes and, for detailed invoices, existing item codes. Enter each item on a separate row, or use the supported totals-only layout.","Iš oficialaus pardavimų importo straipsnio atsisiųskite Rekinu_Imp_2024.xlsx. Naudokite esamus klientų, o detalioms sąskaitoms – prekių kodus. Kiekvieną prekę įrašykite atskiroje eilutėje arba naudokite palaikomą suminį variantą."],["Preserve the workbook structure and the 200-row limit. Open Realizācija → Importi → Rēķinu imports, select the XLSX and confirm. Check the resulting records in Realizācija → Rēķini.","Išlaikykite šablono struktūrą ir 200 eilučių ribą. Atverkite Realizācija → Importi → Rēķinu imports, pasirinkite XLSX ir patvirtinkite. Rezultatą tikrinkite Realizācija → Rēķini."]])],"MONEO API":[n(["Enable access for the correct company","Prieiga konkrečiai įmonei"],"MONEO",[["Arrange an API integration licence and API user with MONEO. Confirm the allowed server IP addresses and the user’s access to the required company and tables.","Su MONEO suderinkite API integracijos licenciją ir API naudotoją. Patvirtinkite leidžiamus serverio IP adresus bei naudotojo teises reikiamai įmonei ir lentelėms."],["Find the API address and company ID in MONEO → Palīdzība → Servera informācija. In FH select MONEO API and enter the matching API URL and compuid. Keys belong in the server connection, not document notes.","API adresą ir įmonės ID raskite MONEO → Palīdzība → Servera informācija. FH pasirinkite MONEO API ir atitinkamus API URL bei compuid. Raktai skirti serverio jungčiai, ne dokumento pastaboms."]]),n(["Request and receipt","Užklausa ir rezultatas"],"MONEO",[["MONEO requests use the Authorization header and request.compuid. The workflow describes separate read/create operations: a POST request alone does not mean that an invoice is created. Use the exact record-creation operation and schema from the vendor documentation.","MONEO užklausose naudojama Authorization antraštė ir request.compuid. Darbo eigoje atskirtos skaitymo ir kūrimo operacijos: vien POST dar nereiškia sąskaitos sukūrimo. Naudokite dokumentacijoje nurodytą kūrimo operaciją ir struktūrą."],["Select the appropriate table; sales.invoices is the sales-invoice table. Obtain the purchase table and line schema from the official table reference. Check the returned record identifier and errors before marking delivery complete.","Parinkite tinkamą lentelę: sales.invoices skirta pardavimo sąskaitoms. Pirkimų lentelę ir eilučių struktūrą tikrinkite oficialiame lentelių apraše. Prieš užbaigdami perdavimą patikrinkite grąžintą įrašo ID ir klaidas."]])],"Jumis Excel":[n(["Select the correct Excel example","Tinkamo Excel pavyzdžio pasirinkimas"],"Jumis",[["Use the official XLSX example for financial or stock documents, not an arbitrary worksheet. Red-marked fields are mandatory; keep paired additional-information fields together. Use the exact destination codes.","Naudokite oficialų finansinių arba sandėlio dokumentų XLSX pavyzdį, ne laisvą lentelę. Raudonai pažymėti laukai privalomi; susijusius papildomos informacijos laukus pildykite kartu. Naudokite tikslius gavėjo kodus."],["Open Konfigurācija → Jumis datu imports. Set Datu veids to Excel and choose the completed file. Resolve mapping prompts against existing records, then check imported documents.","Atverkite Konfigurācija → Jumis datu imports. Lauke Datu veids pasirinkite Excel ir užpildytą failą. Susiekite prašomas reikšmes su esamais įrašais, tada patikrinkite importuotus dokumentus."],["For non-EUR financial documents, check currencies and exchange rates in both document and posting sheets. Do not treat an invoice PDF as an Excel import file.","Ne EUR finansiniams dokumentams tikrinkite valiutas ir kursus dokumento bei korespondencijų lapuose. Sąskaitos PDF nėra Excel importo failas."]])],"Jumis XML":[n(["XML import","XML failo importas"],"Jumis",[["Use a sample exported from the intended Jumis document type and its official XML specification. Financial and stock documents have different structures. A generic XML export is not automatically compatible.","Naudokite iš reikiamo Jumis dokumento tipo eksportuotą pavyzdį ir oficialią XML specifikaciją. Finansinių ir sandėlio dokumentų struktūros skiriasi. Bendras XML failas savaime netinka."],["Open Konfigurēšana → Tj datu imports, select the matching XML and follow the import checks. Verify the document and accounting result after import.","Atverkite Konfigurēšana → Tj datu imports, pasirinkite tinkamą XML ir atlikite importo patikrą. Po importo sutikrinkite dokumentą ir apskaitos rezultatą."]])],"Jumis API":[n(["Cloud API access","Debesijos API prieiga"],"Jumis",[["The documented REST service works with Jumis cloud databases. Obtain the cloud username, special SQL password, database name and API parameters through the administrator. The special password is not the FH password.","Aprašyta REST tarnyba veikia su Jumis debesijos bazėmis. Per administratorių gaukite debesijos naudotoją, specialų SQL slaptažodį, bazės pavadinimą ir API parametrus. Specialus slaptažodis nėra FH slaptažodis."],["The server sends HTTPS POST JSON to the documented import service with username, password, database, apikey and XMLrequest. XMLrequest contains the selected Jumis XML structure. Do not place these credentials in the browser URL.","Serveris į dokumentacijoje nurodytą importo tarnybą siunčia HTTPS POST JSON su username, password, database, apikey ir XMLrequest. XMLrequest talpina pasirinktą Jumis XML struktūrą. Prisijungimų nedėkite į naršyklės URL."],["Read the returned import result and any document errors; an HTTP connection by itself does not confirm successful import.","Perskaitykite grąžintą importo rezultatą bei dokumentų klaidas; vien HTTP ryšys nepatvirtina sėkmingo importo."]])],"Horizon Peppol XML":[n(["Purchase e-invoices in Metarēķini","Pirkimo e. sąskaitos skiltyje Metarēķini"],"Horizon",[["Use a valid Peppol BIS Billing 3.0 invoice XML. A PDF attachment or an arbitrary XML file is not a structured Peppol invoice. Confirm that the receiving company has the Metarēķini functionality and the required document type.","Naudokite taisyklingą Peppol BIS Billing 3.0 sąskaitos XML. PDF priedas ar bet koks XML nėra struktūrinė Peppol sąskaita. Patikrinkite gavėjo įmonės Metarēķini funkcionalumą ir dokumento tipą."],["Open Dokumenti → Metarēķini → Metarēķinu saraksts → Darbības → Imports - PEPPOL formāts, or Metarēķinu imports → Pievienot. Choose the XML and review the import result.","Atverkite Dokumenti → Metarēķini → Metarēķinu saraksts → Darbības → Imports - PEPPOL formāts arba Metarēķinu imports → Pievienot. Pasirinkite XML ir peržiūrėkite rezultatą."],["Review supplier, currency and lines in the intermediate record. A metarēķins is not yet a posted accounting document: complete recognition/approval and generate the final invoice. Agree GL accounts and analytical dimensions separately.","Tarpiniame įraše patikrinkite tiekėją, valiutą ir eilutes. Metarēķins dar nėra užregistruotas apskaitos dokumentas: užbaikite atpažinimą bei derinimą ir sukurkite galutinę sąskaitą. DK ir analitines dimensijas suderinkite atskirai."]])],"Horizon API":[n(["REST connection","REST jungtis"],"Horizon",[["Ask the Horizon administrator to confirm REST access, the integration server address, authentication and permissions for the intended company. Use the official REST documentation linked below.","Paprašykite Horizon administratoriaus patvirtinti REST prieigą, integracijų serverio adresą, autentifikavimą ir teises reikiamai įmonei. Remkitės žemiau pateikta oficialia REST dokumentacija."],["Agree the invoice resource and document-type template for that installation before enabling delivery. Do not use the release-notes API as an accounting endpoint or send Peppol XML to an arbitrary REST URL.","Prieš įjungdami perdavimą suderinkite to diegimo sąskaitos resursą ir dokumento tipo šabloną. Pakeitimų žurnalo API nėra apskaitos galinis taškas; Peppol XML nesiųskite į atsitiktinį REST adresą."],["Configure GL and dimension mappings with the implementer. Check the returned document identifier, import errors and posting state separately.","Su diegėju sukonfigūruokite DK bei dimensijų atitikmenis. Atskirai patikrinkite grąžintą dokumento ID, importo klaidas ir registravimo būseną."]])],"Zalktis XML":[n(["Purchase e-invoices","Pirkimo e. sąskaitos"],"Zalktis",[["Before the first import, configure incoming-invoice posting schemes in Pamatdati → Administratora rīki → Rēķinu un noliktavas dokumentu kontējumu shēmas.","Prieš pirmą importą nustatykite gaunamų sąskaitų korespondencijų schemas: Pamatdati → Administratora rīki → Rēķinu un noliktavas dokumentu kontējumu shēmas."],["Import the structured purchase e-invoice XML from the invoice list. Zalktis checks whether the recipient registration number belongs to your company.","Sąskaitų sąraše importuokite struktūrinį pirkimo e. sąskaitos XML. Zalktis tikrina, ar gavėjo registracijos numeris priklauso jūsų įmonei."],["The imported purchase invoice opens for review. Correct additional information or posting accounts if needed, then save. This route is different from Zalktis accounting-entry XML import.","Importuota pirkimo sąskaita atveriama patikrai. Jei reikia, papildykite informaciją ar korespondencijų sąskaitas ir išsaugokite. Šis būdas skiriasi nuo Zalktis apskaitos įrašų XML importo."]])],"Zalktis Accounting XML":[n(["Accounting-entry XML","Apskaitos įrašų XML"],"Zalktis",[["Use Pamatdati → Administratora rīki → Dažādu datu imports un eksports → Zalktis datu eksports/imports. The file must be UTF-8 and follow the official hierarchical structure.","Naudokite Pamatdati → Administratora rīki → Dažādu datu imports un eksports → Zalktis datu eksports/imports. Failas turi būti UTF-8 ir atitikti oficialią hierarchinę struktūrą."],["The structure starts with Root, contains FailaPase and one or more Dokuments records. Copying these element names alone is not sufficient: use the full provider specification for required fields and postings.","Struktūra prasideda Root, turi FailaPase ir vieną ar daugiau Dokuments įrašų. Vien šių žymų neužtenka: privalomus laukus ir korespondencijas formuokite pagal visą tiekėjo specifikaciją."],["Check document type, date, number, partner, currency and balanced debit/credit entries before importing. The published example is versioned; confirm compatibility with your installed Zalktis version.","Prieš importą patikrinkite tipą, datą, numerį, partnerį, valiutą ir debeto bei kredito balansą. Paskelbtas pavyzdys turi versiją; patvirtinkite jo suderinamumą su savo Zalktis diegimu."]])]},x={title:["FinancialDoc or StoreDoc?","FinancialDoc ar StoreDoc?"],system:"Jumis",paragraphs:[["FinancialDoc describes cash, bank and other financial operations. Its header includes DocNo, DocDate, DocPartnerRegistrationNo, DocAmount and DocCurrency; posting fields include LineDebetAccountCode, LineCreditAccountCode and LineVatRate. These are field references, not a complete import payload.","FinancialDoc aprašo kasos, banko ir kitas finansines operacijas. Antraštėje yra DocNo, DocDate, DocPartnerRegistrationNo, DocAmount ir DocCurrency, korespondencijose – LineDebetAccountCode, LineCreditAccountCode ir LineVatRate. Tai laukų nuorodos, ne pilna importo užklausa."],["StoreDoc is the stock-document structure for goods/service trading documents. Select the structure according to the destination register, not merely because an OCR document is called an invoice. Follow each block’s version and required fields.","StoreDoc yra prekių bei paslaugų prekybos dokumentų sandėlio struktūra. Ją rinkitės pagal gavėjo registrą, ne vien todėl, kad OCR dokumentas pavadintas sąskaita. Laikykitės konkretaus bloko versijos ir privalomų laukų."]]},v=Object.fromEntries(l.map(i=>[i.name,{summary:[`${i.name}: ${i.format}; official import instructions and checks.`,`${i.name}: ${i.format}; oficiali importo eiga ir patikrinimai.`],setup:[`In All Documents → Documents select the organization → gear → Documents & digitization setup → Export format → ${i.name}. Save this organization’s choice.`,`Visi dokumentai → Dokumentai pasirinkite organizaciją → dantratį → Dokumentų ir skaitmeninimo nustatymai → Eksporto formatas → ${i.name}. Išsaugokite šios organizacijos pasirinkimą.`],checks:["Check the receiver, document direction, required codes, currency and totals. File import and API delivery are different methods.","Patikrinkite gavėją, dokumento kryptį, privalomus kodus, valiutą ir sumas. Failo importas ir API siuntimas yra skirtingi būdai."]}])),R=Object.fromEntries(l.map(i=>{const a=v[i.name],s=[{id:"configuration",title:["Configuration and method selection","Konfigūravimas ir būdo pasirinkimas"],description:a.summary,fieldReference:!0,note:m,sections:[n(["Where to configure FH","Kur nustatyti FH"],"FH",[a.setup,["Enter the required non-secret settings and use the help icons for field explanations. Save. API secrets are not retained by this form; a secure server connection must be configured separately.","Užpildykite reikalingus neslaptus nustatymus; laukų paaiškinimus atverkite klaustukais. Išsaugokite. Ši forma API paslapčių nesaugo; saugi serverio jungtis prijungiama atskirai."],["Select documents from one organization. Export selected documents lets you choose the destination for a download; Send to uses the organization’s primary destination. Neither selecting a format nor downloading a preview proves external import.","Pažymėkite vienos organizacijos dokumentus. Eksportuoti pažymėtus dokumentus leidžia pasirinkti atsisiuntimo gavėją, o Siųsti į naudoja organizacijos pagrindinį formatą. Nei formato pasirinkimas, nei peržiūros atsisiuntimas nepatvirtina išorinio importo."]])]},{id:i.method==="api"?"api-transfer":"invoice-import",title:i.method==="api"?["API connection and document delivery","API prijungimas ir dokumentų perdavimas"]:["Invoice import: step by step","Sąskaitų importas žingsnis po žingsnio"],description:a.summary,sections:[...I[i.name],...i.family==="jumis"?[x]:[]],note:m},{id:"workflow-and-checks",title:["Result and errors","Rezultatas ir klaidos"],description:a.checks,sections:[n(["Before import","Prieš importą"],"FH",[a.checks,["Resolve missing required data and reported document issues. Compare the invoice with its original, then use the receiving system’s exact codes.","Užpildykite privalomus duomenis ir išspręskite dokumento klaidas. Sutikrinkite sąskaitą su originalu ir naudokite tikslius gavėjo sistemos kodus."]]),n(["After import","Po importo"],i.family.toUpperCase(),[["Open the created record and compare invoice number, partner, net amount, VAT and total. Check posting separately. If the result is uncertain, search for the document before retrying to avoid duplicates.","Atverkite sukurtą įrašą, palyginkite numerį, partnerį, sumą be PVM, PVM ir bendrą sumą. Registravimą tikrinkite atskirai. Jei rezultatas neaiškus, prieš kartodami ieškokite dokumento, kad nesukurtumėte dublikato."]]),n(["When you need help","Kai reikia pagalbos"],"FH",[["For a rejected import, provide the destination, document number, time and error text. For incorrect OCR values use Report issue. Never include API keys or passwords in messages or screenshots.","Atmesto importo atveju pateikite gavėją, dokumento numerį, laiką ir klaidos tekstą. Klaidingoms OCR reikšmėms naudokite Pranešti apie klaidą. Žinutėse ir nuotraukose nerodykite API raktų ar slaptažodžių."]])],note:i.family==="zalktis"?["The cited Zalktis documentation describes file imports, not a public invoice-upload API. No Zalktis API option is offered without a verified API specification.","Nurodyta Zalktis dokumentacija aprašo failų importą, ne viešą sąskaitų įkėlimo API. Be patvirtintos API specifikacijos Zalktis API pasirinkimas nepateikiamas."]:m}];return[i.name,s.map(o=>({...o,sections:o.sections.map((r,p)=>p?r:{...r,example:{title:["Example","Pavyzdys"],paragraphs:o.id==="configuration"?[[`For Alice Stone select ${i.name}; another organization keeps its own format. ${i.method==="api"?"A saved API URL does not activate a connection.":"Use the official receiving template, not a renamed PDF or preview file."}`,`Alice Stone įmonei pasirinkite ${i.name}; kitos organizacijos formatas nesikeičia. ${i.method==="api"?"Išsaugotas API URL jungties neįjungia.":"Naudokite oficialų gavėjo šabloną, ne pervadintą PDF ar peržiūros failą."}`]]:o.id==="workflow-and-checks"?[["Invoice INV-104 totals 121.00 EUR. Before retrying a failed import, search for INV-104 and the same supplier in the receiving company. If the record exists, compare it instead of importing it a second time.","Sąskaitos INV-104 suma – 121,00 EUR. Prieš kartodami nesėkmingą importą gavėjo įmonėje ieškokite INV-104 ir to paties tiekėjo. Jei įrašas yra, jį sutikrinkite, neimportuokite antrą kartą."]]:[[`Example invoice INV-104: net 100.00 EUR, VAT 21.00 EUR, total 121.00 EUR. Map its real supplier and GL codes to the ${i.format} specification; after import, all three amounts must agree with the original invoice.`,`Pavyzdinė sąskaita INV-104: be PVM 100,00 EUR, PVM 21,00 EUR, iš viso 121,00 EUR. Tikrus tiekėjo ir DK kodus susiekite pagal ${i.format} specifikaciją; po importo visos trys sumos turi sutapti su originalu.`]]}}),related:s.filter(r=>r.id!==o.id).map(r=>({topic:r.id,label:r.title}))}))]})),E=i=>{const a=l.find(s=>s.name===i);return a?w[a.family]:[]},t=(i,a,s)=>({summary:i,setup:a,checks:s}),D={...v,Agnum:t(["Invoice file for Agnum, with expense / item codes, VAT and warehouse allocation.","Sąskaitų failas „Agnum“ su išlaidų ar prekių kodais, PVM ir sandėlių paskirstymu."],["Match Agnum item and warehouse codes. Configure the item account code and registration-number preference, then download the selected invoices for import in Agnum.","Suderinkite „Agnum“ prekių ir sandėlių kodus. Nustatykite prekės sąskaitos kodą bei registracijos numerio parinktį, tada atsisiųskite pažymėtas sąskaitas importui į „Agnum“."],["Check warehouse, VAT and item codes; unpack a ZIP before selecting its import files. Compare invoice numbers to avoid duplicates.","Patikrinkite sandėlio, PVM ir prekių kodus; ZIP išarchyvuokite prieš rinkdamiesi importo failus. Sutikrinkite sąskaitų numerius, kad nesusidarytų dublikatų."]),Apskaita5:t(["File-based invoice transfer to Apskaita5.","Sąskaitų perdavimas į „Apskaita5“ failu."],["Use the expense / income and VAT codes of the receiving company. This form has no API credentials; generate a file and use the destination import function.","Naudokite gavėjo įmonės išlaidų ar pajamų ir PVM kodus. Šioje formoje API prisijungimo laukų nėra: sugeneruokite failą ir naudokite gavėjo importo funkciją."],["Check the selected company, code mappings and the import specification supported by your Apskaita5 installation.","Patikrinkite pasirinktą įmonę, kodų atitikmenis ir jūsų „Apskaita5“ diegimo palaikomą importo specifikaciją."]),BSS:t(["BSS file import; this is separate from BSS Api.","BSS failo importas; tai atskiras pasirinkimas nuo „BSS Api“."],["Map tax, warehouse, department and expense codes. BSS imports may use an Excel data file and an XML template: load a new template first if the receiving setup requires it.","Susiekite mokesčių, sandėlio, padalinio ir išlaidų kodus. BSS importas gali naudoti „Excel“ duomenis ir XML šabloną: jei gavėjo nustatymams reikia naujo šablono, jį įkelkite pirmą."],["Check that the BSS import template matches the file columns. A successful download is not a completed BSS import.","Patikrinkite, ar BSS importo šablonas atitinka failo stulpelius. Sėkmingas atsisiuntimas dar nereiškia importo į BSS."]),"BSS Api":t(["Direct BSS connection settings, including optional API v2 settings.","Tiesioginio BSS ryšio nustatymai, įskaitant neprivalomą API v2 konfigūraciją."],["Obtain the server URL, integration username, API key and portfolio from BSS. For v2, use the supplied URL, environment and company identifiers; do not mix two environments.","Iš BSS gaukite serverio adresą, integracijos naudotoją, API raktą ir portfelį. V2 atveju naudokite pateiktą adresą, aplinkos ir įmonės identifikatorius; nemaišykite skirtingų aplinkų."],["Check portfolio / company access, credential expiry and which API version your BSS installation accepts.","Patikrinkite portfelio bei įmonės prieigą, prisijungimo duomenų galiojimą ir jūsų BSS diegimo API versiją."]),"Business Central":t(["OAuth-based Business Central invoice integration.","„Business Central“ sąskaitų integracija su OAuth autorizacija."],["The administrator provides the authorization URL, company API URL, client ID and secret. Confirm that the required invoice API extension is installed; a generic BC URL is not necessarily compatible.","Administratorius pateikia autorizacijos adresą, įmonės API adresą, kliento ID ir slaptą reikšmę. Patikrinkite, ar įdiegtas reikiamas sąskaitų API plėtinys; bendras BC adresas nebūtinai tinka."],["Check tenant, environment, company ID, customer / supplier templates and product / VAT posting groups.","Patikrinkite nuomininką, aplinką, įmonės ID, pirkėjų ir tiekėjų šablonus bei prekių ir PVM registravimo grupes."]),Būtent:t(["Būtent invoice export with warehouse, operation and cost codes.","„Būtent“ sąskaitų eksportas su sandėlio, operacijos ir sąnaudų kodais."],["Select the Būtent import variant agreed with your accountant. Map codes and decide whether non-positive amounts should be ignored before generating a file.","Pasirinkite su buhalteriu suderintą „Būtent“ importo variantą. Susiekite kodus ir prieš generuodami failą nustatykite, ar praleisti neteigiamas sumas."],["Inspect omitted zero / negative lines and check that credit documents remain represented correctly.","Patikrinkite praleistas nulines ar neigiamas eilutes ir ar teisingai pateikti kreditiniai dokumentai."]),"Būtent kiekinis":t(["Quantity-based Būtent export preserving item-level allocation.","Kiekinis „Būtent“ eksportas su prekių eilučių paskirstymu."],["Use this variant for item quantities and prices. Check every item code, quantity, unit and warehouse rather than allocating only the document total.","Šį variantą rinkitės prekių kiekiams ir kainoms. Tikrinkite kiekvienos eilutės kodą, kiekį, vienetą ir sandėlį, ne tik bendrą dokumento sumą."],["Compare line totals to the invoice and review the non-positive amount option.","Sutikrinkite eilučių sumas su sąskaita ir neteigiamų sumų praleidimo parinktį."]),Centas:t(["Centas file export with item debit, credit and revenue mappings.","Failo eksportas į „Centas“ su prekės debeto, kredito ir pajamų sąskaitomis."],["Enter account codes from Centas and match item / service, warehouse, object and VAT codes. Import the downloaded file in the correct company.","Įrašykite „Centas“ sąskaitų kodus, suderinkite prekių ar paslaugų, sandėlio, objekto ir PVM kodus. Atsisiųstą failą importuokite reikiamoje įmonėje."],["Check counterparty duplicates, currency and the import format supported by the receiving Centas version.","Patikrinkite kontrahentų dublikatus, valiutą ir gavėjo „Centas“ versijos palaikomą importo formatą."]),CSV:t(["A tabular exchange file, not a direct accounting connection.","Lentelinis duomenų failas, o ne tiesioginis ryšys su apskaita."],["Agree the column mapping, separator, date format and decimal format with the receiving system. Export a sample and check it before a batch import.","Su gavėjo sistema suderinkite stulpelių atitikmenis, skirtuką, datos ir dešimtainių skaičių formatą. Prieš masinį importą patikrinkite vieną pavyzdį."],["Preserve leading zeros in codes. Opening and saving in Excel can change dates or identifiers.","Išsaugokite pradžioje esančius kodų nulius. Atidarius ir išsaugojus per „Excel“ gali pasikeisti datos arba identifikatoriai."]),Debetas:t(["Debetas file export with branch and credit-account settings.","„Debetas“ failo eksportas su filialo ir kredito sąskaitos nustatymais."],["Set branch and credit codes; map department, object, expense article, materially responsible person and VAT. Use the receiving Debetas import module.","Nustatykite filialo ir kredito kodus; susiekite padalinį, objektą, išlaidų straipsnį, materialiai atsakingą asmenį bei PVM. Naudokite gavėjo „Debetas“ importo modulį."],["Check codes against the receiving company, not just their display names. Debetas Excel is a different format.","Kodų atitikimą tikrinkite gavėjo įmonėje, ne vien pagal pavadinimus. „Debetas Excel“ yra kitas formatas."]),"Debetas Excel":t(["Spreadsheet variant for Debetas.","Skaičiuoklės variantas „Debetas“ sistemai."],["Map department, object, expense and VAT codes. Select Debetas Excel specifically when the receiving import expects a spreadsheet.","Susiekite padalinio, objekto, išlaidų ir PVM kodus. „Debetas Excel“ rinkitės tada, kai gavėjo importui reikia skaičiuoklės."],["Keep the generated column order and code formatting; do not substitute a generic Excel export.","Išlaikykite sugeneruotų stulpelių tvarką ir kodų formatą; nekeiskite šio varianto bendru „Excel“ eksportu."]),Dineta:t(["Dineta connection using a service URL and integration credentials.","„Dineta“ ryšys naudojant paslaugos adresą ir integracijos prisijungimo duomenis."],["Ask the Dineta representative for the integration username, password and server URL. Select purchase / sales GL templates and the correct warehouse.","Iš „Dineta“ atstovo gaukite integracijos naudotoją, slaptažodį ir serverio adresą. Parinkite pirkimų bei pardavimų DK šablonus ir sandėlį."],["Check server address, integration-user rights and the template / warehouse codes of the target company.","Patikrinkite serverio adresą, integracijos naudotojo teises ir gavėjo įmonės šablonų bei sandėlių kodus."]),Directo:t(["Directo has separate purchase and sales API key fields in FH.","FH „Directo“ nustatymuose yra atskiri pirkimų ir pardavimų API raktų laukai."],["Obtain both keys needed for your document directions. Map warehouse, expense and VAT; choose when additional-column defaults should be assigned.","Gaukite naudojamoms dokumentų kryptims reikalingus raktus. Susiekite sandėlį, išlaidas ir PVM; pasirinkite papildomų stulpelių priskyrimo etapą."],["A valid purchase key does not establish sales access. Check direction, key scope and exact codes.","Tinkamas pirkimų raktas nesuteikia pardavimų prieigos. Tikrinkite kryptį, rakto teises ir tikslius kodus."]),Euroskaita:t(["Euroskaita file export with type and warehouse allocation.","„Euroskaita“ failo eksportas su tipo ir sandėlio paskirstymu."],["Match document type, warehouse, expense and VAT codes to Euroskaita, then import the generated file through the receiving system.","Suderinkite dokumento tipo, sandėlio, išlaidų ir PVM kodus su „Euroskaita“, tada importuokite sugeneruotą failą gavėjo sistemoje."],["Confirm the destination import specification before using FH sample files for real accounting.","Prieš naudodami FH pavyzdinius failus tikrai apskaitai patvirtinkite gavėjo importo specifikaciją."]),Excel:t(["General spreadsheet export for review or a separately mapped import.","Bendras skaičiuoklės eksportas peržiūrai arba atskirai suderintam importui."],["Download selected records and map the columns to the recipient’s template. Choose a named accounting format instead when it has a dedicated adapter.","Atsisiųskite pažymėtus įrašus ir susiekite stulpelius su gavėjo šablonu. Jei yra specialus apskaitos formatas, naudokite jį."],["Check dates, numeric precision and text codes. A spreadsheet is not automatically compatible with every accounting program.","Patikrinkite datas, skaičių tikslumą ir tekstinius kodus. Skaičiuoklė savaime nėra suderinama su kiekviena apskaitos programa."]),Finvalda:t(["Finvalda file export with item kind, warehouse, type and journal codes.","„Finvalda“ failo eksportas su prekės rūšies, sandėlio, tipo ir žurnalo kodais."],["Check the destination VAT and debit / credit mappings. In Finvalda use Data import → From file, choose the file and review the import result.","Patikrinkite gavėjo PVM ir debeto bei kredito atitikmenis. „Finvalda“ naudokite Duomenų importas → Iš failo, pasirinkite failą ir peržiūrėkite importo rezultatą."],["Check new-item account links, VAT and warehouse defaults in Finvalda. FH codes must match that company’s codes.","Patikrinkite naujų prekių sąskaitų ryšį, PVM ir sandėlio numatytąsias reikšmes „Finvalda“ sistemoje. FH kodai turi sutapti su tos įmonės kodais."]),"Finvalda Excel":t(["Finvalda spreadsheet variant with type, expense and VAT allocation.","„Finvalda“ skaičiuoklės variantas su tipo, išlaidų ir PVM paskirstymu."],["Choose the spreadsheet import template accepted by your Finvalda installation. Keep type, expense and VAT columns mapped to the receiving codes.","Pasirinkite jūsų „Finvalda“ diegimui tinkamą skaičiuoklės importo šabloną. Tipo, išlaidų ir PVM stulpelius susiekite su gavėjo kodais."],["Do not interchange this file with the regular Finvalda format without checking the import template.","Nekeiskite šio failo įprastu „Finvalda“ formatu nepatikrinę importo šablono."]),iSAF:t(["Invoice-register export format; it is not a general-ledger posting integration.","Sąskaitų registro eksporto formatas; tai nėra DK operacijų registravimo integracija."],["Check company identifiers, invoice numbers, dates, purchase / sale direction and VAT classification before generating the register file.","Prieš generuodami registro failą patikrinkite įmonių identifikatorius, numerius, datas, pirkimo ar pardavimo kryptį ir PVM klasifikaciją."],["Validate the final production file with the receiving register specification. FH preview export does not submit a declaration.","Galutinį produkcinį failą tikrinkite pagal gavėjo registro specifikaciją. FH peržiūros eksportas deklaracijos nepateikia."]),Json:t(["Structured JSON data for a separately implemented receiving adapter.","Struktūriniai JSON duomenys atskirai įdiegtam gavėjo adapteriui."],["Agree property names, document / line structure and code mappings with the receiving developer. This format is a file, not the FH API key.","Su gavėjo programuotoju suderinkite laukų pavadinimus, dokumento bei eilučių struktūrą ir kodų atitikmenis. Šis formatas yra failas, ne FH API raktas."],["Check schema, decimal values, dates and required identifiers. Do not equate downloading JSON with API delivery.","Tikrinkite schemą, skaičius, datas ir privalomus identifikatorius. JSON atsisiuntimas nėra perdavimas per API."]),Lobasoft:t(["Lobasoft file export using the common invoice settings.","„Lobasoft“ failo eksportas naudojant bendrus sąskaitų nustatymus."],["Set expense and VAT mappings and common export preferences. Confirm the Lobasoft file specification with its administrator before importing.","Nustatykite išlaidų ir PVM atitikmenis bei bendras eksporto parinktis. Prieš importą su administratoriumi patvirtinkite „Lobasoft“ failo specifikaciją."],["This form has no live Lobasoft login. Check import validation and document totals in the receiving system.","Ši forma neturi aktyvaus „Lobasoft“ prisijungimo. Patikrinkite importo validaciją ir dokumentų sumas gavėjo sistemoje."]),Monet:t(["Monet export with an identification code and correspondence mapping.","„Monet“ eksportas su identifikavimo kodu ir korespondencijos atitikmenimis."],["Use the identification code supplied for your Monet setup. Map correspondence, expense and VAT codes before preparing the export.","Naudokite jūsų „Monet“ konfigūracijai suteiktą identifikavimo kodą. Prieš eksportą susiekite korespondencijos, išlaidų ir PVM kodus."],["An identification code is not proof of an active connection. Confirm the delivery/import method with the Monet administrator.","Identifikavimo kodas nepatvirtina aktyvaus ryšio. Perdavimo ar importo būdą patvirtinkite su „Monet“ administratoriumi."]),Odoo:t(["Odoo service settings with default product and payable-account mappings.","„Odoo“ paslaugos nustatymai su numatytąja preke ir mokėtinų sumų sąskaita."],["Obtain the API URL, client ID and client password for the agreed adapter. Enter the default product name and payable account, then map VAT and expense codes.","Gaukite suderinto adapterio API adresą, kliento ID ir slaptažodį. Įrašykite numatytosios prekės pavadinimą bei mokėtinų sumų sąskaitą, susiekite PVM ir išlaidų kodus."],["Confirm adapter compatibility, company access and account codes; Odoo versions and custom modules can differ.","Patikrinkite adapterio suderinamumą, įmonės prieigą ir sąskaitų kodus: „Odoo“ versijos bei individualūs moduliai gali skirtis."]),Optimum:t(["Optimum API transfer with defaults for newly created records.","Perdavimas per „Optimum“ API su naujų įrašų numatytosiomis reikšmėmis."],["In Optimum, the API key is available through Help → API key. Configure VAT account, customer / supplier / product groups and item defaults for the selected company.","„Optimum“ API raktą rasite Pagalba → API raktas. Pasirinktai įmonei nustatykite PVM sąskaitą, pirkėjų, tiekėjų bei prekių grupes ir prekių numatytąsias reikšmes."],["Check missing related codes, allowed code length, employee / warehouse mappings and rejected non-positive lines.","Patikrinkite trūkstamus susijusius kodus, leidžiamą jų ilgį, darbuotojų bei sandėlių atitikmenis ir atmestas neteigiamas eilutes."]),Paulita:t(["Paulita invoice export after expense / income allocation.","„Paulita“ sąskaitų eksportas priskyrus išlaidų ar pajamų kodus."],["Allocate expense / income and VAT codes. Download the chosen Paulita format and import it in the intended company in Paulita.","Priskirkite išlaidų ar pajamų ir PVM kodus. Atsisiųskite pasirinktą „Paulita“ formatą ir importuokite jį reikiamoje „Paulita“ įmonėje."],["Confirm file compatibility and compare invoice totals after import; no API credentials are configured here.","Patvirtinkite failo suderinamumą ir po importo sutikrinkite sumas; API prisijungimo duomenys čia nekonfigūruojami."]),Pragma3:t(["Pragma3 file with debit / credit and credit-document sign rules.","„Pragma3“ failas su debeto, kredito ir kreditinių dokumentų ženklų taisyklėmis."],["Set debit and credit codes, credit-note direction and warehouse / project mappings. Use the Pragma3 import specification, not a Pragma4 template.","Nustatykite debeto bei kredito kodus, kreditinių dokumentų kryptį ir sandėlio bei projektų atitikmenis. Naudokite „Pragma3“, ne „Pragma4“ importo specifikaciją."],["Check supplier codes and negative quantity / amount rules before retrying a rejected document.","Prieš kartodami atmestą dokumentą patikrinkite tiekėjo kodą ir neigiamo kiekio bei sumos taisykles."]),Pragma4:t(["Pragma4 file with credit-document sign preferences.","„Pragma4“ failas su kreditinių dokumentų ženklų parinktimis."],["Map warehouse, correspondence, item and VAT codes. Choose the credit purchase / sales sign rules agreed with the receiving setup.","Susiekite sandėlio, korespondencijos, prekių ir PVM kodus. Parinkite su gavėju suderintas kreditinių pirkimų ir pardavimų ženklų taisykles."],["Check whether counterparties already exist and whether your import expects Pragma4 or Pragma4 V2.","Patikrinkite, ar kontrahentai jau sukurti ir ar importui reikia „Pragma4“, ar „Pragma4 V2“."]),"Pragma4 V2":t(["A separate Pragma4 import variant.","Atskiras „Pragma4“ importo variantas."],["Use V2 only when the receiving template requires it. Match warehouse, correspondence, item and VAT codes to that template.","V2 rinkitės tik tada, kai jo reikia gavėjo šablonui. Su šablonu suderinkite sandėlio, korespondencijos, prekių ir PVM kodus."],["Changing the format name does not convert a destination template. Verify one document with the administrator first.","Formato pavadinimo pakeitimas nepakeičia gavėjo šablono. Pirmiausia su administratoriumi patikrinkite vieną dokumentą."]),Rivilė:t(["Rivilė GAMA file export; direct API is a separate selection.","„Rivilė GAMA“ failo eksportas; tiesioginė API yra atskiras pasirinkimas."],["Configure item account links, item type, payment-account codes and purchase / sales operation types. Match analytical codes, then download and import the file in GAMA.","Nustatykite prekių sąskaitų ryšį, prekės tipą, apmokėjimo sąskaitų kodus bei pirkimo ir pardavimo operacijų tipus. Susiekite analitinius kodus, atsisiųskite ir importuokite failą į GAMA."],["Check item / service / code type, account-link code, department and VAT. A file download does not need the GAMA API key.","Tikrinkite prekės, paslaugos ar kodo tipą, sąskaitų ryšio kodą, padalinį ir PVM. Failo atsisiuntimui GAMA API rakto nereikia."]),"Rivilė API":t(["Rivilė GAMA direct integration through Manorivile-Gateway.","Tiesioginė „Rivilė GAMA“ integracija per „Manorivile-Gateway“."],["The Rivilė administrator enables API access for the company database, issues a key and configures Gateway. Set code updates and automatic posting separately from document creation.","Rivilės administratorius įjungia API konkrečiai įmonės bazei, suteikia raktą ir sukonfigūruoja „Gateway“. Kodų atnaujinimą ir automatinį perkėlimą nustatykite atskirai nuo dokumento sukūrimo."],["401: key / access; 502: Gateway connection; timeout: check whether the document was created before retrying. See the full Rivilė API error guide.","401: raktas ar prieiga; 502: „Gateway“ ryšys; pasibaigus laukimui prieš kartojimą patikrinkite, ar dokumentas sukurtas. Žr. išsamų Rivilė API klaidų aprašymą."]),"Rivilė ERP":t(["Rivilė ERP integration with its own API key, separate from GAMA.","„Rivilė ERP“ integracija su atskiru API raktu, nesusijusiu su GAMA."],["Create the ERP key for the intended company and integration permissions. Match product / service, department, object and VAT codes.","ERP raktą sukurkite reikiamai įmonei ir integracijos teisėms. Suderinkite prekių ar paslaugų, padalinio, objekto ir PVM kodus."],["Check key expiry and company assignment. A GAMA key and Gateway configuration are not ERP credentials.","Patikrinkite rakto galiojimą ir įmonės priskyrimą. GAMA raktas ir „Gateway“ konfigūracija nėra ERP prisijungimo duomenys."]),Roda:t(["Roda export with department, object, expense and VAT mappings.","„Roda“ eksportas su padalinio, objekto, išlaidų ir PVM atitikmenimis."],["Set the receiving company’s codes and common export preferences. Obtain the accepted file specification from the Roda administrator.","Nustatykite gavėjo įmonės kodus ir bendras eksporto parinktis. Priimamą failo specifikaciją gaukite iš „Roda“ administratoriaus."],["No direct-connection credentials appear in this form; verify the file in the receiving import before production use.","Tiesioginio prisijungimo laukų šioje formoje nėra; prieš naudojimą produkcijoje failą patikrinkite gavėjo importe."]),Saikas:t(["Saikas file export with separate purchase / sales and VAT accounts.","„Saikas“ failo eksportas su atskiromis pirkimų, pardavimų ir PVM sąskaitomis."],["Set the four account mappings and department / expense / VAT codes. In Saikas use Functions → Data import, choose the purchase or sales template, read the file and review it.","Nustatykite keturis sąskaitų atitikmenis bei padalinio, išlaidų ir PVM kodus. „Saikas“ rinkitės Funkcijos → Duomenų importavimas, pirkimų ar pardavimų šabloną, nuskaitykite failą ir jį patikrinkite."],["Check document direction and the selected import template before registering the result.","Prieš registruodami rezultatą patikrinkite dokumento kryptį ir pasirinktą importo šabloną."]),"Site.pro":t(["Site.pro API invoice transfer with warehouse and operation mappings.","Sąskaitų perdavimas per „Site.pro“ API su sandėlio ir operacijos atitikmenimis."],["Ask the Site.pro administrator to enable API #2 for the company and provide its key. Match warehouse, operation, expense and VAT codes; review negative-credit preferences.","Paprašykite „Site.pro“ administratoriaus įjungti įmonės API #2 ir pateikti raktą. Susiekite sandėlio, operacijos, išlaidų ir PVM kodus; patikrinkite neigiamų kreditinių sumų parinktis."],["For an item-date conflict, review the stock chronology and document dates. Do not alter factual invoice dates merely to bypass an error.","Prekės datos konflikto atveju tikrinkite atsargų chronologiją ir dokumentų datas. Nekeiskite faktinių sąskaitos datų vien tam, kad apeitumėte klaidą."]),StandardERP:t(["StandardERP export with warehouse and accounting-code allocation.","„StandardERP“ eksportas su sandėlio ir apskaitos kodų paskirstymu."],["Map warehouse, expense and VAT codes, then agree the import file variant with your StandardERP administrator.","Susiekite sandėlio, išlaidų ir PVM kodus, tuomet su „StandardERP“ administratoriumi suderinkite importo failo variantą."],["Confirm exact code values and file compatibility; this form has no active StandardERP connection.","Patvirtinkite tikslias kodų reikšmes ir failo suderinamumą; ši forma neturi aktyvaus „StandardERP“ ryšio."]),Syrve:t(["Syrve API integration for item / stock-related invoices.","„Syrve“ API integracija prekių ir atsargų sąskaitoms."],["Obtain the API URL and integration credentials. Match products, warehouses and concepts; review raw-material-only, quantity-recalculation and create-product preferences.","Gaukite API adresą ir integracijos prisijungimo duomenis. Suderinkite prekes, sandėlius ir koncepcijas; peržiūrėkite žaliavų, kiekio perskaičiavimo ir prekių kūrimo parinktis."],["If a product is not found, check its exact code in Syrve and the selected warehouse. Verify quantities and units after any recalculation.","Jei prekė nerasta, patikrinkite tikslų jos kodą „Syrve“ bei sandėlį. Po perskaičiavimo sutikrinkite kiekius ir mato vienetus."]),"UCS StoreHouse v4":t(["StoreHouse v4 export settings include a destination email address.","„StoreHouse v4“ eksporto nustatymuose yra gavėjo el. pašto adresas."],["Confirm the receiving email with the administrator, then map department and expense codes. Configure actual mail delivery on the server before using it.","Su administratoriumi patvirtinkite gavėjo el. paštą, susiekite padalinio bei išlaidų kodus. Prieš naudojimą serveryje turi būti sukonfigūruotas tikras laiškų siuntimas."],["Saving an address sends no mail. Check delivery and the receiving import result separately.","Adreso išsaugojimas laiško nesiunčia. Pristatymą ir gavėjo importo rezultatą tikrinkite atskirai."]),Uniconta:t(["Uniconta file-format selection with common invoice preferences.","„Uniconta“ failo formato pasirinkimas su bendromis sąskaitų parinktimis."],["Match expense and VAT codes and confirm the accepted import template with the Uniconta administrator.","Susiekite išlaidų bei PVM kodus ir su „Uniconta“ administratoriumi patvirtinkite priimamą importo šabloną."],["No Uniconta credentials are configured here; confirm the actual receiving adapter before production import.","„Uniconta“ prisijungimo duomenys čia nekonfigūruojami; prieš produkcinį importą patvirtinkite gavėjo adapterį."]),XML:t(["Structured XML file for a separately agreed receiving schema.","Struktūrinis XML failas pagal atskirai suderintą gavėjo schemą."],["Agree element names, required fields and department / object / expense / VAT mappings. A named system’s XML is not necessarily equivalent to this generic format.","Suderinkite elementų pavadinimus, privalomus laukus ir padalinio, objekto, išlaidų bei PVM atitikmenis. Konkrečios sistemos XML nebūtinai sutampa su šiuo bendru formatu."],["Validate against the destination schema, including encoding, decimal values and dates.","Tikrinkite pagal gavėjo schemą, įskaitant koduotę, dešimtaines reikšmes ir datas."])},T=[{id:"email",name:["Email","El. paštas"],group:"collection",method:"email",summary:["Receive invoice attachments through the FH document-upload mailbox.","Gaukite sąskaitų priedus per FH dokumentų įkėlimo pašto dėžutę."],setup:["Use only the upload address displayed in your FH account. It is not the user’s login email or the recipient for payment reminders.","Naudokite tik jūsų FH paskyroje rodomą įkėlimo adresą. Tai ne naudotojo prisijungimo el. paštas ir ne mokėjimų priminimų gavėjas."],checks:["Check the exact recipient, attached files and rejected-mail response. A sent email alone does not prove that its documents were imported.","Patikrinkite tikslų gavėją, pridėtus failus ir laiško atmetimo atsakymą. Išsiųstas laiškas dar neįrodo, kad dokumentai importuoti."],steps:[["Find the document email address in the Dashboard upload area.","Dokumentų el. paštą raskite Apžvalgos įkėlimo srityje."],["Attach the invoice files and send them to the configured receiving mailbox.","Pridėkite sąskaitų failus ir siųskite į sukonfigūruotą gavimo pašto dėžutę."],["In a connected service, received files appear in All Documents → Uploaded documents with Email as their source and the sender address beneath it.","Prijungtoje tarnyboje gauti failai atsiranda Visi dokumentai → Įkelti dokumentai, su šaltiniu „El. paštas“ ir siuntėjo adresu po juo."],["Follow Processing / Needs attention. Organization recognition and OCR review use the same workflow as manual upload.","Sekite apdorojimą ir dėmesio reikalaujančius įrašus. Organizacijos atpažinimas ir OCR peržiūra veikia pagal tą pačią eigą kaip rankinis įkėlimas."]]},{id:"google-drive",name:["Google Drive","Google Drive"],group:"collection",method:"folder",summary:["Two separate directions: incoming files to OCR and processed PDFs to an archive.","Dvi atskiros kryptys: gaunami failai į OCR ir apdoroti PDF į archyvą."],setup:["Profile settings → Setup & integration → Google Drive. Configure the incoming folder and archive independently. FH must use its own service account and authorization.","Profilio nustatymai → Nustatymai ir integracija → Google Drive. Gaunamų dokumentų aplanką ir archyvą konfigūruokite atskirai. FH turi naudoti savo tarnybinę paskyrą ir autorizaciją."],checks:["Check the account, folder address, access and shared-drive ID. Removing folder access stops a connected reader; it does not delete the source files.","Tikrinkite paskyrą, aplanko adresą, prieigą ir bendro disko ID. Pašalinus prieigą sustoja prijungtas skaitytuvas, bet pradiniai failai neištrinami."],fields:[{label:["Import folder / URL","Importo aplankas / adresas"],description:["The incoming folder, not a single-file link. Include subfolders only when required.","Gaunamų dokumentų aplankas, ne atskiro failo nuoroda. Poaplankius įtraukite tik prireikus."]},{label:["Archive folder","Archyvo aplankas"],description:["Destination for processed documents; keep it separate from the incoming folder to avoid re-import loops.","Apdorotų dokumentų paskirties vieta; atskirkite nuo gavimo aplanko, kad nebūtų pakartotinio importo ciklų."]},{label:["Shared drive ID","Bendro disko ID"],description:["Only the identifier of a Google Workspace shared drive; leave empty for a personal drive.","Tik „Google Workspace“ bendro disko identifikatorius; asmeniniam diskui palikite tuščią."]}],steps:[["Set the folder name / URL and the Include subfolders preference.","Nustatykite aplanko pavadinimą ar adresą ir poaplankių įtraukimo parinktį."],["After the backend connector is installed, grant its FH service account access to the intended folder only.","Įdiegus serverio jungtį, suteikite jos FH tarnybinei paskyrai prieigą tik prie reikiamo aplanko."],["Check connection before enabling scheduled reading. Saving preferences alone does not read Google Drive.","Prieš įjungdami periodinį skaitymą patikrinkite ryšį. Vien parinkčių išsaugojimas „Google Drive“ neskaito."],["For archiving, authorize the destination separately and confirm which organizations and periods to include.","Archyvavimui paskirties vietą autorizuokite atskirai ir patvirtinkite įtraukiamas organizacijas bei laikotarpius."]],links:[{label:"Google Drive · Sharing and permissions",url:"https://support.google.com/drive/answer/7166529"}]},{id:"sharepoint",name:["SharePoint","SharePoint"],group:"collection",method:"folder",summary:["Read documents from configured SharePoint libraries or folders into OCR.","Dokumentų skaitymas į OCR iš nustatytų „SharePoint“ bibliotekų ar aplankų."],setup:["Profile settings → Setup & integration → SharePoint. The Microsoft administrator provides the app registration, tenant ID and client ID, and stores the secret through a secure backend.","Profilio nustatymai → Nustatymai ir integracija → SharePoint. „Microsoft“ administratorius paruošia programos registraciją, nuomininko bei kliento ID, o slaptą reikšmę saugo per saugų serverį."],checks:["Check secret expiry, tenant / app IDs, granted site access and the folder path. Never grant access to every site merely to make a connection test pass.","Tikrinkite slaptos reikšmės galiojimą, nuomininko bei programos ID, suteiktą svetainės prieigą ir aplanko kelią. Nesuteikite visų svetainių prieigos vien tam, kad pavyktų ryšio testas."],fields:[{label:["Tenant ID","Nuomininko ID"],description:["Microsoft organization identifier.","„Microsoft“ organizacijos identifikatorius."]},{label:["Client ID","Kliento ID"],description:["Identifier of the registered integration application, not a user email.","Registruotos integracijos programos identifikatorius, ne naudotojo el. paštas."]},{label:["Client secret","Slapta kliento reikšmė"],description:["Secret value, not the secret ID. The frontend does not store this credential.","Slaptoji reikšmė, ne jos ID. Frontend šio prisijungimo duomens nesaugo."]},{label:["SharePoint URLs / schedule","SharePoint adresai / grafikas"],description:["One library or folder URL per line; choose frequency and, for a daily run, time. The server must confirm timezone and path-pattern support.","Po vieną bibliotekos ar aplanko adresą eilutėje; pasirinkite dažnį, o kasdieniam vykdymui – laiką. Laiko juostą ir kelio šablonų palaikymą turi patvirtinti serveris."]}],steps:[["In Microsoft Entra, ask the administrator to select the FH application registration.","„Microsoft Entra“ paprašykite administratoriaus pasirinkti FH programos registraciją."],["Grant the least permissions supported by the connector. Selected-site permission also requires an explicit grant to that site.","Suteikite mažiausias jungties palaikomas teises. Pasirinktų svetainių leidimui taip pat reikia atskiro prieigos suteikimo tai svetainei."],["Enter library / folder URLs, not a sharing link to one file, and set the reading schedule.","Įrašykite bibliotekos ar aplanko adresus, ne vieno failo bendrinimo nuorodą, ir nustatykite skaitymo grafiką."],["After server connection, check a permitted folder and follow imported documents in Uploaded documents.","Prijungę serverį patikrinkite leistiną aplanką ir sekite gautus dokumentus skiltyje Įkelti dokumentai."]],links:[{label:"Microsoft Learn · Selected permissions",url:"https://learn.microsoft.com/en-us/graph/permissions-selected-overview"},{label:"Microsoft Entra",url:"https://entra.microsoft.com/"}]},{id:"fh-api",name:["FH API","FH API"],group:"collection",method:"api",summary:["Programmatic document upload and result retrieval; different from an accounting provider’s API key.","Programinis dokumentų įkėlimas ir rezultatų gavimas; skiriasi nuo apskaitos tiekėjo API rakto."],setup:["Profile settings → Setup & integration → Working with the system → API access. Choose a key label and only the required upload / result-reading permissions.","Profilio nustatymai → Nustatymai ir integracija → Darbas su sistema → API prieiga. Pasirinkite rakto pavadinimą ir tik reikalingas įkėlimo bei rezultatų skaitymo teises."],checks:["The current frontend generates no API key and exposes no documented production endpoint. Do not put credentials in query strings, screenshots or browser storage.","Dabartinis frontend API rakto nesukuria ir neturi aprašyto produkcinio galinio taško. Raktų nedėkite į URL parametrus, ekrano nuotraukas ar naršyklės saugyklą."],steps:[["Save the desired access and permission preferences.","Išsaugokite pageidaujamą prieigą ir teisių parinktis."],["Before connecting another app, obtain the deployed FH API specification and server-issued credential from the administrator.","Prieš prijungdami kitą programą iš administratoriaus gaukite įdiegtos FH API specifikaciją ir serverio išduotą raktą."],["The connected client uploads a document and keeps the returned identifier; processing is asynchronous.","Prijungtas klientas įkelia dokumentą ir išsaugo gautą identifikatorių; apdorojimas vyksta asinchroniškai."],["Read the processing result using that identifier. A received request is not yet a processed or exported invoice.","Pagal identifikatorių perskaitykite apdorojimo rezultatą. Gauta užklausa dar nereiškia apdorotos ar eksportuotos sąskaitos."]]},{id:"dropbox",name:["Dropbox","Dropbox"],group:"collection",method:"planned",summary:["Dropbox can be shown as a document source; no Dropbox connection form is implemented in this version.","„Dropbox“ gali būti rodomas kaip dokumento šaltinis; šioje versijoje „Dropbox“ prijungimo forma neįgyvendinta."],setup:["For now, download documents from your Dropbox and use the FH upload area. A source label in a sample record does not establish synchronization.","Kol kas atsisiųskite dokumentus iš savo „Dropbox“ ir naudokite FH įkėlimo sritį. Šaltinio žyma pavyzdiniame įraše sinchronizavimo nesukuria."],checks:["Automatic collection requires a dedicated connector, authorization, folder selection and duplicate controls. None are activated by this help page.","Automatiniam surinkimui reikia atskiros jungties, autorizacijos, aplanko pasirinkimo ir dublikatų kontrolės. Šis pagalbos puslapis jų neįjungia."],steps:[["Download the intended invoice files from Dropbox.","Atsisiųskite reikiamus sąskaitų failus iš „Dropbox“."],["Upload them through Dashboard or All Documents → Uploaded documents.","Įkelkite juos per Apžvalgą arba Visi dokumentai → Įkelti dokumentai."],["Follow their processing in the standard OCR workflow.","Sekite jų apdorojimą įprastoje OCR darbų eigoje."]]}],c=[...T,...Object.keys(b).map(i=>({id:i,name:[i,i],group:"accounting",method:j.includes(i)?"api":i==="UCS StoreHouse v4"?"email":"file",...D[i],links:E(i)}))];function Y(i){return c.find(a=>a.id===i)||c.find(a=>a.id==="Rivilė API")}const M={codes:[["In All Documents → Documents select the organization → gear → Additional columns → the relevant code list. For expenses choose Code, Service or Product, then Import from Excel.","Visi dokumentai → Dokumentai pasirinkite organizaciją → dantratis → Papildomi stulpeliai → atitinkamas kodų sąrašas. Išlaidoms pasirinkite Kodas, Paslauga arba Prekė, tada Įkelti iš Excel."],["Paste code and name as two TAB-separated columns, one record per line. Remove headings, preserve leading zeros and check the preview before importing. Existing document allocations are not changed by loading a directory.","Įklijuokite du TAB atskirtus stulpelius: kodą ir pavadinimą, po vieną įrašą eilutėje. Pašalinkite antraštes, išsaugokite pradinius nulius ir patikrinkite peržiūrą. Registro įkėlimas nekeičia esamų dokumentų paskirstymo."],["Return to the document and assign the saved code in the corresponding field. If the format has no separate directory for that dimension, use its Additional column settings default; this does not create a missing document-level picker.","Grįžę į dokumentą priskirkite išsaugotą kodą atitinkamame lauke. Jei dimensijai nėra atskiro registro, naudokite formato Papildomų stulpelių numatytąją reikšmę; tai nesukuria trūkstamo pasirinkimo dokumento eilutėje."]],settings:[["Open All Documents → Documents → select organization → gear → Documents & digitization setup. Select this integration and change only the settings for that company.","Atverkite Visi dokumentai → Dokumentai → pasirinkite organizaciją → dantratis → Dokumentų ir skaitmeninimo nustatymai. Pasirinkite šią integraciją; pakeitimai skirti tik tai įmonei."],["Use the field descriptions on the integration overview. Save non-secret settings, review required additional columns and inspect one invoice before a batch. The frontend does not establish a live connection or save / send real credentials.","Laukų reikšmes rasite integracijos apžvalgoje. Išsaugokite ne slaptus nustatymus, patikrinkite privalomus papildomus stulpelius ir prieš paketą peržiūrėkite vieną sąskaitą. Frontend neužmezga tikro ryšio ir tikrų raktų nesaugo bei nesiunčia."]],review:[["In FH open the affected document with Edit and compare the original invoice with the reported field. Correct the code or allocation, not the invoice facts merely to bypass an error.","FH atverkite dokumentą per Redaguoti ir sutikrinkite klaidoje minimą lauką su originalu. Taisykite kodą ar paskirstymą, o ne sąskaitos faktus vien tam, kad apeitumėte klaidą."],["If the correction belongs to OCR, use Report issue and explain the discrepancy to the Worker. Before any real retry, check the destination for an existing invoice; a timeout does not prove that nothing was imported.","Jei reikia OCR korekcijos, rinkitės Pranešti apie klaidą ir darbuotojui aprašykite neatitikimą. Prieš tikrą pakartotinį siuntimą patikrinkite, ar gavėjo sistemoje sąskaitos jau nėra: laukimo laiko pabaiga neįrodo, kad importas neįvyko."]]},e=(i,a,s,o,r,p="settings",k)=>({id:i,title:a,sourceArticleIds:o,description:[r[0][0],r[0][1]],sections:[{title:[`${s}: procedure and checks`,`${s}: eiga ir patikrinimai`],system:s,steps:r},{title:["Continue in Finansų harmonija","Veiksmai Finansų harmonijoje"],system:"FH",steps:M[p]}],note:k,...p==="codes"?{screenshot:{file:"expense-import.jpg",caption:["FH code-list import. Select the appropriate directory and type before pasting.","FH kodų sąrašo įkėlimas. Prieš įklijuodami pasirinkite tinkamą registrą ir tipą."]}}:{}}),g=[e("invoice-import",["Invoice import and templates","Sąskaitų importas ir šablonai"],"BSS",[10673425],[["Choose file import or API; they are separate routes.","Pasirinkite failo importą arba API – tai atskiri būdai."],["For files, extract the ZIP containing XLSX invoice data and the XML import template.","Failo būdu išskleiskite ZIP su XLSX sąskaitų duomenimis ir XML importo šablonu."],["If updating the template, import its XML first. Otherwise keep the existing matching template.","Jei atnaujinate šabloną, pirma įkelkite jo XML. Kitu atveju palikite esamą tinkamą šabloną."],["Choose the purchase or sales XLSX, select the matching import template, then continue with Toliau >.","Pasirinkite pirkimų arba pardavimų XLSX, atitinkantį importo šabloną ir tęskite mygtuku Toliau >."],["For API instead, obtain the BSS integration username, key, portfolio and server URL. Configure BSS Api, not the file template.","API būdui gaukite BSS integracijos naudotoją, raktą, portfelį ir serverio URL. Konfigūruokite BSS Api, ne failo šabloną."]]),e("product-codes",["Product, service and discount codes","Prekių, paslaugų ir nuolaidų kodai"],"BSS",[11325175],[["Use the BSS product register as the source of identifiers.","Identifikatorius imkite iš BSS produktų registro."],["Open Products, display all required records and use the table context menu to export to Excel. Remove the image column and keep product code plus name.","Atverkite Produktai, parodykite reikiamus įrašus ir lentelės kontekstiniame meniu eksportuokite į Excel. Pašalinkite paveikslėlio stulpelį, palikite produkto kodą ir pavadinimą."],["Keep the distinction between products, services and discount codes when choosing the FH code type.","Parinkdami FH kodo tipą išlaikykite skirtumą tarp prekių, paslaugų ir nuolaidų kodų."]],"codes"),e("departments",["Department codes","Padalinių kodai"],"BSS",[11325348],[["Department identifiers must match the BSS directory.","Padalinių identifikatoriai turi sutapti su BSS registru."],["Open Departments, display all required rows and export the table to Excel from its context menu. Copy code and name, then use FH Additional columns → Departments.","Atverkite Padaliniai, parodykite reikiamas eilutes ir kontekstiniame meniu eksportuokite lentelę į Excel. Nukopijuokite kodą bei pavadinimą ir FH rinkitės Papildomi stulpeliai → Padaliniai."]],"codes"),e("tax-codes",["Tax codes and VAT mapping","Mokesčių kodai ir PVM atitikmenys"],"BSS",[11325534],[["A BSS tax code is an identifier, not simply a VAT percentage.","BSS mokesčio kodas yra identifikatorius, ne vien PVM procentas."],["Open Taxes, show the required records and export the table to Excel. Use the Tax code value from that list when configuring the BSS tax field in FH.","Atverkite Mokesčiai, parodykite reikiamus įrašus ir eksportuokite lentelę į Excel. FH BSS mokesčio laukui naudokite šio sąrašo Mokesčio kodas reikšmę."],["Check the document VAT classifier separately; do not replace a code with a percentage such as 21.","Atskirai patikrinkite dokumento PVM klasifikatorių; kodo nekeiskite vien procentu, pavyzdžiui, 21."]]),e("accountable-persons",["Accountable persons: list and assignment","Atskaitingi asmenys: sąrašas ir priskyrimas"],"BSS",[10913926,11330409],[["The assigned person must have an existing BSS code.","Priskiriamas asmuo turi turėti BSS egzistuojantį kodą."],["Open Accountable → Accountable persons. Show the Code column and export the table to Excel. Copy the person code and name.","Atverkite Atskaitingi → Atskaitingi asmenys. Įjunkite Kodas stulpelį ir eksportuokite lentelę į Excel. Nukopijuokite asmens kodą bei vardą ir pavardę."],["Import into the FH accountable-person code directory and check the code selected for the document. A name alone does not identify a BSS person.","Įkelkite į FH atskaitingų asmenų kodų registrą ir patikrinkite dokumentui pasirinktą kodą. Vien vardas ir pavardė BSS asmens neidentifikuoja."]],"codes"),e("api-v2",["API v2 and expense synchronization","API v2 ir išlaidų sinchronizavimas"],"BSS",[12394522],[["API v2 uses its own server and environment identifiers.","API v2 naudoja savo serverio ir aplinkos identifikatorius."],["Ask BSS for the v2 URL, integration username and password, environment ID and company ID. All values must refer to the same installation and company.","Iš BSS gaukite v2 adresą, integracijos naudotoją bei slaptažodį, aplinkos ID ir įmonės ID. Visi duomenys turi priklausyti tam pačiam diegimui ir įmonei."],["FH exposes these configuration fields, but has no live BSS expense-sync service. Until it is connected, use the manual code import instead of expecting an automatic refresh.","FH turi šiuos konfigūravimo laukus, bet tikra BSS išlaidų sinchronizavimo tarnyba neprijungta. Iki jos prijungimo naudokite rankinį kodų įkėlimą, ne automatinį atnaujinimą."]]),e("zero-price",["Error: price cannot be zero","Klaida: kaina negali būti lygi nuliui"],"BSS",[13543605],[["A zero-priced line can be rejected by the BSS product-card rules.","Nulinės kainos eilutę gali atmesti BSS produkto kortelės taisyklės."],["If the item is genuinely supplied free of charge, review the product-card setting allowing free supply. Do not invent a nonzero invoice price merely to avoid the validation.","Jei prekė iš tikrųjų suteikiama nemokamai, peržiūrėkite produkto kortelės nustatymą „Galima suteikti nemokamai“. Nekeiskite faktinės sąskaitos kainos vien tam, kad apeitumėte tikrinimą."]],"review")],u={Apskaita5:[e("item-codes",["Importing item and service codes","Prekių ir paslaugų kodų įkėlimas"],"Apskaita5",[6758268],[["Copy identifiers from the Apskaita5 item catalog.","Identifikatorius kopijuokite iš Apskaita5 prekių katalogo."],["Open Item catalog → Print preview and save the list as Excel. Arrange the identifier in the first column and its description in the second; copy only data rows.","Atverkite Prekių katalogas → Spausdinimo peržiūra ir išsaugokite sąrašą Excel formatu. Pirmame stulpelyje palikite kodą, antrame – aprašymą; kopijuokite tik duomenų eilutes."]],"codes")],BSS:g.filter(i=>i.id!=="api-v2"),"BSS Api":g,"Business Central":[e("oauth-connection",["OAuth, company endpoint and invoice extension","OAuth, įmonės adresas ir sąskaitų plėtinys"],"Business Central",[12050553],[["The invoice endpoint must be supplied by the installed integration extension.","Sąskaitų adresą turi pateikti įdiegtas integracijos plėtinys."],["For the documented Softera eInvoice route, confirm that its required API package is installed. Obtain the tenant, environment and company IDs from the administrator; a generic Business Central endpoint is not equivalent.","Aprašytam Softera eInvoice būdui patikrinkite, ar įdiegtas reikiamas API paketas. Iš administratoriaus gaukite nuomininko, aplinkos bei įmonės ID; bendras Business Central adresas nėra lygiavertis."],["Use the tenant OAuth v2 token address, the application client ID and its secret. The company API URL must point to the same tenant and environment. Never copy example IDs into production.","Naudokite nuomininko OAuth v2 rakto gavimo adresą, programos kliento ID ir slaptą reikšmę. Įmonės API adresas turi priklausyti tam pačiam nuomininkui bei aplinkai. Pavyzdinių ID į produkciją nekopijuokite."]])],Centas:[e("invoice-import",["First import and item cards","Pirmas importas ir prekių kortelės"],"Centas",[6324925],[["Select the company: Parametrai → Įmonės.","Pasirinkite įmonę: Parametrai → Įmonės."],["Export codes: Žinynai → Prekės → Nustatymai → Eksportas → Prekių sąrašas XLS. Retain code and name.","Iškelkite kodus: Žinynai → Prekės → Nustatymai → Eksportas → Prekių sąrašas XLS. Palikite kodą ir pavadinimą."],["Unpack the compatible production export. New item cards use Žinynai → Prekės → Importas → Kortelių įkėlimas/atnaujinimas and CSV selection.","Išskleiskite suderinamą produkcinį eksportą. Naujos prekių kortelės: Žinynai → Prekės → Importas → Kortelių įkėlimas/atnaujinimas ir CSV pasirinkimas."],["For invoices open Darbas → Duomenų importas → Nuosavas formatas.","Sąskaitoms atverkite Darbas → Duomenų importas → Nuosavas formatas."],["Choose purchase / sales direction and XML, not the item-card CSV. Select the invoice file and import.","Pasirinkite pirkimų / pardavimų kryptį ir XML, ne prekių kortelių CSV. Pasirinkite sąskaitų failą ir importuokite."]]),e("original-document",["Viewing the original invoice","Sąskaitos originalo peržiūra"],"Centas",[7177287],[["An original-document link is separate from imported accounting values.","Originalo nuoroda yra atskira nuo importuotų apskaitos reikšmių."],["In Centas, right-click the document and choose View original document. The link must have been included by the import and remain accessible.","Centas paspauskite dokumentą dešiniuoju pelės mygtuku ir rinkitės Peržiūrėti dokumento originalą. Nuoroda turi būti perduota importu ir išlikti pasiekiama."]],"review"),e("duplicate-counterparties",["Duplicate counterparties","Pasikartojantys kontrahentai"],"Centas",[4006791],[["Different accounting and company codes can produce two cards for one counterparty.","Skirtingi apskaitos ir įmonės kodai gali sukurti dvi to paties kontrahento korteles."],["Compare Code and Company code before another import. Have the Centas administrator review linked transactions and a backup before any merge or removal; never delete a card solely because its name matches.","Prieš kitą importą palyginkite Kodas ir Įmonės kodas. Prieš sujungimą ar šalinimą administratorius turi patikrinti susijusias operacijas bei atsarginę kopiją; vien sutampantis pavadinimas nėra pagrindas trinti kortelę."],["Where a correction requires balances to be rebuilt, the Centas reconciliation tool is under Additional → Info → Recalculate current counterparty debts.","Jei po korekcijos reikia perskaičiuoti likučius, Centas veiksmas yra Papildoma → Info → Perskaičiuoti aktualių kontrahentų įsiskolinimą."]],"review"),e("currencies",["Currency and exchange rates","Valiuta ir valiutų kursai"],"Centas",[9506728],[["The invoice currency must exist in Centas.","Sąskaitos valiuta turi egzistuoti Centas."],["Open Work → Accounting → Exchange rates. Add the missing currency, confirm its code and rate, then update the rates. Verify the rate for the invoice date before retrying.","Atverkite Darbas → Buhalterija → Valiutų kursai. Pridėkite trūkstamą valiutą, patvirtinkite jos kodą bei kursą ir atnaujinkite kursus. Prieš kartodami tikrinkite sąskaitos datos kursą."]],"review")],Debetas:[e("invoice-import",["Invoice file and allocations","Sąskaitų failas ir paskirstymas"],"Debetas",[9545706],[["Debetas uses destination-specific codes before its document import.","Debetas importui reikalingi gavėjo sistemos kodai."],["Check expense / income allocation, department, object, expense article and VAT classification. The documented non-Excel route imports a text file through the Debetas import module; Debetas Excel is a different variant.","Patikrinkite išlaidų ar pajamų paskirstymą, padalinį, objektą, išlaidų straipsnį bei PVM klasifikatorių. Aprašytas ne Excel būdas importuoja tekstinį failą per Debetas importo modulį; Debetas Excel yra atskiras variantas."]]),e("expense-articles",["Expense article codes","Išlaidų straipsnių kodai"],"Debetas",[12352713],[["Use the expense-article identifier supplied by the Debetas administrator.","Naudokite Debetas administratoriaus pateiktą išlaidų straipsnio identifikatorių."],["The reference for this topic contained only a video, so an unverified Debetas menu path is not reproduced here. In FH the Debetas export schema has an Expense article default under Additional column settings.","Šios temos šaltinyje buvo tik vaizdo įrašas, todėl nepatikrintas Debetas meniu kelias čia nepateikiamas. FH Debetas formato Papildomų stulpelių nustatymuose yra Išlaidų straipsnio numatytoji reikšmė."]])],Dineta:[e("connection",["Integration user, server and templates","Integracijos naudotojas, serveris ir šablonai"],"Dineta",[11579553],[["Dineta access requires an integration account supplied by the provider.","Dineta prieigai reikalinga tiekėjo suteikta integracijos paskyra."],["Ask Dineta for the username and password and confirm the server URL used by your installation. Do not substitute a browser login path for the agreed integration URL.","Iš Dineta gaukite naudotoją bei slaptažodį ir patvirtinkite jūsų diegimo serverio adresą. Vietoj suderinto integracijos adreso nenaudokite naršyklės prisijungimo kelio."],["In FH select the purchase and sales GL templates and warehouse codes for the same company. Rights and network access must be configured by the provider before a live connector can work.","FH parinkite tos pačios įmonės pirkimo ir pardavimo DK šablonus bei sandėlio kodus. Tiekėjas turi suteikti teises ir tinklo prieigą prieš naudojant tikrą jungtį."]])],Finvalda:[e("invoice-import",["Invoice import and accounting parameters","Sąskaitų importas ir apskaitos parametrai"],"Finvalda",[5172154],[["In Finvalda settings check debit, credit and VAT accounts.","Finvalda nustatymuose patikrinkite debeto, kredito ir PVM sąskaitas."],["For new items, check account links and VAT. In import parameters, VA controls department, employee and warehouse.","Naujoms prekėms patikrinkite sąskaitų ryšį bei PVM. Importo parametruose VA valdo padalinį, darbuotoją ir sandėlį."],["Assign the receiving expense / income codes to the invoices in FH.","FH sąskaitoms priskirkite gavėjo išlaidų / pajamų kodus."],["With a compatible production file, open Duomenų importas in Finvalda and select Iš failo.","Turėdami suderinamą produkcinį failą, Finvalda atverkite Duomenų importas ir pažymėkite Iš failo."],["Click Naršyti, choose the file, inspect the loaded records and confirm the result.","Spauskite Naršyti, pasirinkite failą, peržiūrėkite nuskaitytus įrašus ir patvirtinkite rezultatą."]]),e("service-codes",["Service code list","Paslaugų kodų sąrašas"],"Finvalda",[7887844],[["The service register supplies the exact codes used by Finvalda.","Tikslūs Finvalda kodai imami iš paslaugų registro."],["Open Descriptions → Services → List. Select the required rows (Ctrl+A for all) and copy (Ctrl+C). Arrange code and name into two columns before pasting into FH.","Atverkite Aprašymai → Paslaugos → Sąrašas. Pažymėkite eilutes (visas – Ctrl+A) ir kopijuokite Ctrl+C. Prieš įklijuodami FH išdėstykite kodą bei pavadinimą dviem stulpeliais."]],"codes")],Monet:[e("identification-code",["Creating the identification code","Identifikacinio kodo sukūrimas"],"Monet",[17757400],[["Monet identifies this import through an ExternalInvoice integration code.","Monet šį importą atpažįsta pagal ExternalInvoice integracijos kodą."],["Open Settings → Other → Integration. Create an ExternalInvoice entry, give it a name and save. Open its parameters and obtain the identifying Code.","Atverkite Nustatymai → Kita → Integravimas. Sukurkite ExternalInvoice įrašą, nurodykite pavadinimą ir išsaugokite. Atverkite parametrus ir paimkite identifikacinį Code."],["Enter that value in the FH Identification code field. It is not a user password and does not make the current file-export preview a live API connection.","Reikšmę įrašykite FH lauke Identifikacinis kodas. Tai ne naudotojo slaptažodis ir jis nepaverčia dabartinės failo eksporto peržiūros tikru API ryšiu."]])],Optimum:[e("api-and-import",["API key and first transfer","API raktas ir pirmas perdavimas"],"Optimum",[5161093,9856893],[["The API key is available in Optimum under Help → API key.","Optimum API raktas pasiekiamas per Pagalba → API raktas."],["Match product, service or GL codes and choose the corresponding type. The receiving invoice list is Operations → Invoices; check it after a real transfer.","Suderinkite prekių, paslaugų arba DK kodus ir parinkite atitinkamą tipą. Gavėjo sąskaitų sąrašas yra Operacijos → Sąskaitos-faktūros; po tikro perdavimo tikrinkite jį."]]),e("missing-related-data",["Error: related data is missing","Klaida: trūksta susijusių duomenų"],"Optimum",[4184813],[["A missing country record can trigger a related-data error, including fkCities.","Trūkstamas šalies įrašas gali sukelti susijusių duomenų klaidą, įskaitant fkCities."],["Check Organization → Data → Countries and the invoice country. The expected country identifier is an uppercase two-letter ISO code. Add the actual missing country, not an arbitrary replacement.","Patikrinkite Organizacija → Duomenys → Šalys ir sąskaitos šalį. Tikimasi dviejų didžiųjų raidžių ISO kodo. Įtraukite tikrą trūkstamą šalį, ne atsitiktinį pakaitalą."]],"review"),e("number-pattern",["Error: document number does not match the pattern","Klaida: numeris neatitinka šablono"],"Optimum",[4179768],[["The operation type can restrict the accepted document-number pattern.","Operacijos tipas gali riboti priimamą dokumento numerio šabloną."],["Review General ledger → Data → Operation types → SF invoice → Document number pattern. Ask the administrator to adjust an inappropriate restriction; do not change the legal invoice number to fit it.","Peržiūrėkite Didžioji knyga → Duomenys → Operacijų tipai → SF Sąskaita-faktūra → Dokumentų Nr. šablonas. Netinkamą ribojimą turi pataisyti administratorius; nekeiskite tikro sąskaitos numerio, kad jis tiktų šablonui."]],"review"),e("missing-vat-account",["Error: Account.AccountId is empty","Klaida: neužpildyta Account.AccountId"],"Optimum",[4131237],[["The input VAT account may be absent from the receiving chart of accounts.","Gautino PVM sąskaitos gali nebūti gavėjo sąskaitų plane."],["Compare the configured input VAT account with the company chart. The reference uses 2441 as an example, not a universal account. Enter the actual existing account in FH Optimum settings.","Sutikrinkite nustatytą gautino PVM sąskaitą su įmonės sąskaitų planu. Šaltinyje 2441 yra pavyzdys, ne universali sąskaita. FH Optimum nustatymuose įrašykite iš tikrųjų egzistuojančią sąskaitą."]],"review"),e("duplicate-record",["Error: duplicate number, code or name","Klaida: kartojasi numeris, kodas ar pavadinimas"],"Optimum",[12033483],[["First distinguish an existing invoice from a conflicting directory code.","Pirmiausia atskirkite jau esamą sąskaitą nuo sutampančio registro kodo."],["Search by invoice number and counterparty before retrying. If the invoice is absent, inspect directory codes, including empty values and collisions with 00. Do not remove posted records automatically.","Prieš kartodami ieškokite pagal sąskaitos numerį ir kontrahentą. Jei sąskaitos nėra, patikrinkite registrų kodus, įskaitant tuščias reikšmes ir sutapimus su 00. Užregistruotų operacijų automatiškai nešalinkite."]],"review"),e("missing-employee",["Error: employee code is not found","Klaida: darbuotojo kodas nerastas"],"Optimum",[14617754],[["The Optimum user and employee identities must have compatible codes.","Optimum naudotojo ir darbuotojo tapatybės turi būti susietos tinkamais kodais."],["Have the administrator check the employee directory against the user used for the integration. Correct the mapping or add the actual missing employee; avoid creating a second person for the same identity.","Administratorius turi sutikrinti darbuotojų registrą su integracijai naudojamu naudotoju. Taisykite atitikmenį arba pridėkite tikrą trūkstamą darbuotoją; nekurkite antro įrašo tam pačiam asmeniui."]],"review"),e("service-unit-cost",["Error: unit cost supplied for a service","Klaida: nurodyta paslaugos vieneto savikaina"],"Optimum",[16880874],[["This error can indicate a mismatch between Service and Product.","Ši klaida gali reikšti neatitikimą tarp Paslaugos ir Prekės tipų."],["Review the Optimum item card: Gaminys = No represents a service; Yes represents a product. Match the FH type to the real card and invoice rather than changing amounts.","Patikrinkite Optimum kortelę: Gaminys = Ne reiškia paslaugą, Taip – prekę. FH tipą suderinkite su tikra kortele ir sąskaita, nekeisdami sumų."]],"review")],Paulita:[e("invoice-import",["Invoice export and receiving import","Sąskaitų eksportas ir gavėjo importas"],"Paulita",[6504614],[["Allocate expense / income codes before a Paulita invoice import.","Prieš Paulita sąskaitų importą priskirkite išlaidų ar pajamų kodus."],["The described route uses XML. Select the intended company in Paulita and its compatible invoice-import function. The reference does not provide a reliable text menu path, so confirm the exact command for your installed version.","Aprašytas būdas naudoja XML. Paulita pasirinkite reikiamą įmonę ir jos suderinamą sąskaitų importo funkciją. Šaltinyje nėra patikimo tekstinio meniu kelio, todėl konkrečią komandą patikslinkite pagal savo diegimo versiją."]])],Pragma3:[e("codes-and-nomenclature",["Correspondence and nomenclature codes","Korespondencijos ir nomenklatūros kodai"],"Pragma 3",[8407868],[["Pragma 3 uses correspondence codes and product nomenclature identifiers.","Pragma 3 naudoja korespondencijos kodus ir prekių nomenklatūros identifikatorius."],["Copy the correspondence code with its full name. For products use the nomenclature number; configure the import to match by that number, not by an approximate item name.","Nukopijuokite korespondencijos kodą su pilnu pavadinimu. Prekėms naudokite nomenklatūros numerį; importo atitikimą nustatykite pagal jį, ne panašų prekės pavadinimą."]],"codes"),e("unknown-supplier",["Error: supplier is not recognized","Klaida: neatpažintas tiekėjas"],"Pragma",[11754278],[["The import may omit the company records needed to identify the supplier.","Importe gali nebūti įmonių įrašų, reikalingų tiekėjui atpažinti."],["Check the Companies option in the Pragma import dialog, then verify that the supplier code matches the company card. Do not repeatedly import the invoice without fixing its supplier reference.","Pragma importo lange patikrinkite Įmonės parinktį, tada sutikrinkite tiekėjo kodą su kortele. Nekartokite sąskaitos importo nepataisę tiekėjo atitikmens."]],"review")],Pragma4:[e("new-customer",["Creating a missing customer during import","Trūkstamo kliento sukūrimas importuojant"],"Pragma 4",[16144743],[["The import configuration determines whether missing client cards can be created.","Importo nustatymai lemia, ar galima sukurti trūkstamas klientų korteles."],["Check the company code and search existing cards first. If a genuinely new client is not created, ask the Pragma administrator to review the import settings and permissions.","Pirmiausia patikrinkite įmonės kodą ir paieškokite esamų kortelių. Jei tikrai naujas klientas nesukuriamas, paprašykite Pragma administratoriaus patikrinti importo nustatymus bei teises."]],"review")],"Rivilė ERP":[e("erp-api-key",["ERP API key and access","ERP API raktas ir prieiga"],"Rivilė ERP",[9684948,9685697],[["Rivilė ERP uses an ERP key, not a GAMA Gateway key.","Rivilė ERP naudoja ERP raktą, ne GAMA Gateway raktą."],["Open Settings → General → API keys. Create a key with an identifying name and suitable expiry, then store it securely; its full value may only be shown once.","Atverkite Nustatymai → Bendrieji → API raktai. Sukurkite raktą su atpažįstamu pavadinimu ir tinkamu galiojimu, saugiai jį išsaugokite; visa reikšmė gali būti parodyta tik vieną kartą."],["Match department, item / service and VAT codes for the intended organization before using a connected adapter.","Prieš naudodami prijungtą adapterį suderinkite reikiamos organizacijos padalinių, prekių ar paslaugų bei PVM kodus."]]),e("erp-item-codes",["Importing ERP product and service codes","ERP prekių ir paslaugų kodų įkėlimas"],"Rivilė ERP",[9685569],[["Copy the exact ERP identifiers, preserving letter case.","Kopijuokite tikslius ERP identifikatorius, nekeisdami raidžių dydžio."],["Open Settings → Inventory and logistics → Products, services. Filter by type and use More → CSV export. Keep code and name as the first two columns for FH import.","Atverkite Nustatymai → Atsargos ir logistika → Prekės, paslaugos. Filtruokite pagal tipą ir rinkitės Daugiau → Eksportas į CSV. FH įkėlimui pirmuose dviejuose stulpeliuose palikite kodą ir pavadinimą."]],"codes")],Saikas:[e("invoice-import",["Purchase and sales file import","Pirkimų ir pardavimų failo importas"],"Saikas",[8004223],[["Check purchase, purchase VAT, sales and sales VAT account mappings separately.","Atskirai patikrinkite pirkimų, pirkimų PVM, pardavimų ir pardavimų PVM sąskaitų atitikmenis."],["Open Funkcijos → Duomenų importavimas in Saikas.","Saikas atverkite Funkcijos → Duomenų importavimas."],["Select the purchase or sales import template matching your file.","Pasirinkite failą atitinkantį pirkimų arba pardavimų importo šabloną."],["Use Failas to select the compatible production document file, then Nuskaityti failą and Jungtis.","Per Failas pasirinkite suderinamą produkcinį dokumentų failą, tada Nuskaityti failą ir Jungtis."],["Verify records in Programa → Atsargų apskaita → Pirkimai or Pardavimai.","Rezultatą patikrinkite Programa → Atsargų apskaita → Pirkimai arba Pardavimai."]])],"Site.pro":[e("connection-and-key",["Site.pro (formerly B1): API and first transfer","Site.pro (anksčiau B1): API ir pirmas perdavimas"],"Site.pro",[17778730,6560168,6576084],[["The former B1 integration is listed as Site.pro.","Ankstesnė B1 integracija sąraše vadinama Site.pro."],["In Site.pro use Parameters → Integrations → API #2. Enable the required service and obtain the key for the specific company; different companies require their own access.","Site.pro rinkitės Parametrai → Integracijos → API #2. Įjunkite reikiamą paslaugą ir gaukite konkrečios įmonės raktą; skirtingoms įmonėms reikia atskiros prieigos."],["Before transfer, check warehouse, operation, expense and VAT codes. The key alone does not supply these allocations.","Prieš perdavimą patikrinkite sandėlio, operacijos, išlaidų ir PVM kodus. Vien raktas šių paskirstymų neužpildo."]]),e("item-codes",["Item and expense codes","Prekių ir išlaidų kodai"],"Site.pro",[6576680],[["Import the item identifiers used by the receiving company.","Įkelkite gavėjo įmonėje naudojamus prekių identifikatorius."],["Open Directories → Item cards → Items and export to Excel with the cloud action. Copy the code and description columns; include every code needed by the invoice lines.","Atverkite Žinynai → Prekių kortelės → Prekės ir debesies veiksmu eksportuokite į Excel. Nukopijuokite kodą bei aprašymą; įtraukite visus sąskaitų eilutėms reikalingus kodus."]],"codes"),e("operation-codes",["Operation types","Operacijų rūšys"],"Site.pro",[6576201],[["The operation code identifies how the invoice is handled in Site.pro.","Operacijos kodas nurodo, kaip sąskaita tvarkoma Site.pro."],["Open Directories → Warehouse → Operation types and export to Excel. Use the code, not only the name, in the FH Site.pro Operation default.","Atverkite Žinynai → Sandėlio → Operacijos rūšys ir eksportuokite į Excel. FH Site.pro Operacijos numatytajai reikšmei naudokite kodą, ne vien pavadinimą."]]),e("warehouses",["Warehouse allocation","Sandėlio priskyrimas"],"Site.pro",[6576117],[["Choose the warehouse belonging to the correct company.","Rinkitės reikiamai įmonei priklausantį sandėlį."],["Open Directories → Warehouse → Warehouses and export the list to Excel. Confirm with the receiving import whether its warehouse identifier or name is expected; do not assume the spreadsheet column position defines the identifier.","Atverkite Žinynai → Sandėlio → Sandėliai ir eksportuokite sąrašą į Excel. Patikrinkite, ar gavėjo importas tikisi sandėlio identifikatoriaus, ar pavadinimo; vien stulpelio vieta skaičiuoklėje to nenustato."],["FH exposes document and line warehouse defaults; it does not yet provide a separate Site.pro warehouse directory.","FH pateikia dokumento ir eilutės sandėlio numatytąsias reikšmes; atskiro Site.pro sandėlių registro dar nėra."]]),e("item-date-conflict",["Error: item date conflict","Klaida: datos konfliktas prekei"],"Site.pro",[15700973],[["A sale dated before the stock purchase can cause an item-date conflict.","Pardavimas, kurio data ankstesnė už atsargų įsigijimą, gali sukelti prekės datos konfliktą."],["Compare the sales date, purchase receipt date, product and warehouse in Site.pro. Correct a missing or wrongly dated receipt only when supported by the source documents.","Site.pro sutikrinkite pardavimo datą, pirkimo gavimo datą, prekę ir sandėlį. Trūkstamą ar klaidingai datuotą gavimą taisykite tik pagal pirminius dokumentus."],["Do not shift the invoice date merely to pass stock validation. Check the result in the receiving system before sending again.","Nekeiskite sąskaitos datos vien tam, kad apeitumėte atsargų tikrinimą. Prieš kartodami siuntimą patikrinkite rezultatą gavėjo sistemoje."]],"review")],Syrve:[e("connection",["Server address and integration account","Serverio adresas ir integracijos paskyra"],"Syrve",[10365202],[["Use a dedicated Syrve integration user and the correct server.","Naudokite atskirą Syrve integracijos naudotoją ir tinkamą serverį."],["The server protocol, address and port are visible in System Sign-in → More. Confirm credentials and permissions with the Syrve administrator. Do not copy another company’s URL or credentials.","Serverio protokolas, adresas ir prievadas matomi System Sign-in → More. Prisijungimus bei teises suderinkite su Syrve administratoriumi. Nekopijuokite kitos įmonės adreso ar prisijungimų."]]),e("item-codes",["SKU codes and expenses","SKU kodai ir išlaidos"],"Syrve",[12540236],[["Syrve SKU maps to the code; the item name maps to its description.","Syrve SKU atitinka kodą, prekės pavadinimas – jo aprašymą."],["Copy the exact SKU and name into the FH expense / product directory. Automatic refresh requires a live connector; the current FH screen supports manual entry and Excel paste.","Tikslų SKU ir pavadinimą įkelkite į FH išlaidų ar prekių registrą. Automatiniam atnaujinimui reikia tikros jungties; dabartinis FH langas leidžia įvesti ranka arba įklijuoti iš Excel."]],"codes"),e("warehouses",["Warehouse codes","Sandėlių kodai"],"Syrve",[12545700],[["A Syrve warehouse must be identified by its own code.","Syrve sandėlis turi būti atpažįstamas pagal jo kodą."],["Open Inventory Management → Storage → Storages and read the storage code and name. Use the corresponding warehouse default in FH, not the delivery address.","Atverkite Inventory Management → Storage → Storages ir raskite sandėlio kodą bei pavadinimą. FH naudokite atitinkamą sandėlio numatytąją reikšmę, ne pristatymo adresą."]]),e("concepts",["Concept codes","Koncepcijų kodai"],"Syrve",[12545735],[["A concept is a separate Syrve dimension, not a warehouse.","Koncepcija yra atskira Syrve dimensija, ne sandėlis."],["Open Retail Sales → Concepts and obtain the concept code and name. In FH use the Concept default in the Syrve additional-column settings.","Atverkite Retail Sales → Concepts ir paimkite koncepcijos kodą bei pavadinimą. FH naudokite Koncepcijos numatytąją reikšmę Syrve papildomų stulpelių nustatymuose."]]),e("batch-warehouse",["Warehouse for multiple invoice lines","Sandėlis kelioms sąskaitos eilutėms"],"Syrve",[12645142],[["A delivery address does not reliably determine a Syrve warehouse.","Pristatymo adresas neleidžia patikimai nustatyti Syrve sandėlio."],["Verify the intended warehouse before applying it to all lines. FH currently has the format default but not a dedicated Syrve bulk warehouse assignment action; do not assume a different bulk field changes it.","Prieš taikydami visoms eilutėms patikrinkite sandėlį. FH šiuo metu turi formato numatytąją reikšmę, bet neturi atskiro masinio Syrve sandėlio priskyrimo veiksmo; kito masinio lauko keitimas jo nepakeičia."]]),e("quantity-conversion",["Product quantity conversion","Prekių kiekių perskaičiavimas"],"Syrve",[13557673],[["Quantity conversion follows the unit relationship in the Syrve product card.","Kiekių perskaičiavimas remiasi vienetų santykiu Syrve prekės kortelėje."],["For example, ten packages at 0.9 kg each represent 9 kg. Check the source unit, target unit and coefficient; the invoice total must remain consistent.","Pavyzdžiui, dešimt pakuočių po 0,9 kg sudaro 9 kg. Patikrinkite pradinį bei tikslinį vienetą ir koeficientą; sąskaitos suma turi išlikti suderinta."],["FH exposes the quantity-recalculation option as a setting. Without a connected Syrve adapter it does not fetch the product card or perform a verified stock conversion.","FH pateikia kiekių perskaičiavimo parinktį kaip nustatymą. Be prijungto Syrve adapterio ji negauna prekės kortelės ir neatlieka patikrinto atsargų perskaičiavimo."]]),e("product-not-found",["Error: outer product was not found","Klaida: prekė nerasta Syrve"],"Syrve",[15250845],[["The external-raw-materials-only filter can hide an otherwise existing product.","Tik išorinių žaliavų filtras gali paslėpti net egzistuojančią prekę."],["Compare the exact SKU and product card, then review the External raw materials only option. Do not create another product until you have ruled out filtering and a wrong code.","Sutikrinkite tikslų SKU bei prekės kortelę ir peržiūrėkite Tik išorinės žaliavos parinktį. Nekurkite antros prekės, kol neatmetėte filtro ar netinkamo kodo priežasties."]],"review")]},y=[e("file-import",["EIP file import order","EIP failų importavimo tvarka"],"Rivilė GAMA",[8630489],[["The client and item records must be available before the invoices that reference them.","Klientų ir prekių įrašai turi būti įkelti prieš juos naudojančias sąskaitas."],["Unpack the compatible production archive before choosing files in Rivilė GAMA.","Prieš rinkdamiesi failus Rivilė GAMA, išskleiskite suderinamą produkcinį archyvą."],["Import Klientai.eip first, in the intended company database.","Reikiamoje įmonės bazėje pirmiausia importuokite Klientai.eip."],["If supplied and required, import Prekes.eip next.","Jei pateiktas ir reikalingas, toliau importuokite Prekes.eip."],["Finally import Pirkimai.eip or Pardavimai.eip for the corresponding direction. Check the resulting invoices before repeating a file.","Galiausiai atitinkama kryptimi importuokite Pirkimai.eip arba Pardavimai.eip. Prieš kartodami failą patikrinkite gautas sąskaitas."],["These are the receiving system’s production-file requirements. The current FH preview file is not an EIP adapter and must not be imported as a production file.","Tai gavėjo sistemos produkcinių failų reikalavimai. Dabartinis FH peržiūros failas nėra EIP adapteris ir neturi būti importuojamas kaip produkcinis failas."]]),e("expense-allocation",["Expense / income allocation","Išlaidų ir pajamų paskirstymas"],"Rivilė GAMA",[3508472],[["Expense allocation can use a Rivilė code rather than a supplier item identifier.","Išlaidų paskirstymui galima naudoti Rivilės kodą, o ne tiekėjo prekės identifikatorių."],["Check Cards → 05 Codes and use its exact code in FH. Names, spaces and letter case must not silently replace the actual identifier.","Patikrinkite Kortelės → 05 Kodai ir FH naudokite tikslų kodą. Pavadinimas, tarpai ar pakeistas raidžių dydis neturi pakeisti tikro identifikatoriaus."]],"codes"),e("gateway-api",["GAMA API key and Gateway","GAMA API raktas ir Gateway"],"Rivilė GAMA",[5166019],[["Direct transfer requires API access for the intended GAMA database and a working Gateway.","Tiesioginiam perdavimui reikia reikiamos GAMA bazės API prieigos ir veikiančio Gateway."],["Arrange access with Rivilė or the implementer. Use a separate key for the correct database and have the administrator verify that Gateway reaches it. A key does not replace server configuration.","Prieigą suderinkite su Rivile arba diegėju. Naudokite reikiamai bazei skirtą raktą; administratorius turi patikrinti, ar Gateway ją pasiekia. Raktas nepakeičia serverio konfigūravimo."]]),e("products-services",["Product, service and code types","Prekės, paslaugos ir kodo tipai"],"Rivilė GAMA",[6261192],[["Choose the directory type that exists in the receiving Rivilė database.","Pasirinkite gavėjo Rivilės bazėje egzistuojantį registro tipą."],["A Code, Service and Product are not interchangeable. Import the corresponding list into FH and choose the matching type before assigning a line, especially for quantity-based documents.","Kodas, Paslauga ir Prekė nėra tarpusavyje pakeičiami. Įkelkite atitinkamą sąrašą į FH ir prieš priskirdami eilutę parinkite tipą, ypač kiekinėms sąskaitoms."]],"codes"),e("new-item-settings",["New-item account link, type and group","Naujos prekės sąskaitų ryšys, tipas ir grupė"],"Rivilė GAMA",[8255025,8128349],[["Account-link and type settings concern newly created item cards.","Sąskaitų ryšio ir tipo nustatymai skirti naujai kuriamoms prekių kortelėms."],["Use an existing account-link code. Rivilė item types distinguish ordinary, assembled, disassembled, generated, composite, mixed and packaging items; confirm the correct numeric type with the card settings.","Naudokite egzistuojantį sąskaitų ryšio kodą. Rivilės tipai skiria paprastas, komplektuojamas, išskaidomas, generuojamas, sudėtines, mišrias prekes bei tarą; skaitinį tipą sutikrinkite su kortelės nustatymais."],["FH has Item account link code, Item type and an additional Product group field. Saving them does not update existing cards or create new Rivilė items without a real adapter.","FH turi Prekės sąskaitų ryšio kodą, Prekės tipą ir papildomą Prekių grupės lauką. Jų išsaugojimas nekeičia esamų kortelių ir be tikro adapterio nesukuria Rivilės prekių."]]),e("automatic-export",["Automatic export after digitization","Automatinis eksportas po skaitmeninimo"],"Rivilė GAMA",[9728118],[["Automatic export and accounting posting are separate decisions.","Automatinis eksportas ir dokumento perkėlimas apskaitoje yra atskiri sprendimai."],["In FH Rivilė API settings, Export immediately after digitization expresses the trigger; Automatically post expresses the receiving posting step. Required codes and successful validation must still be checked.","FH Rivilė API nustatymuose Eksportuoti iš karto po skaitmeninimo nurodo paleidimą, o Automatiškai perkelti – gavėjo registravimo veiksmą. Privalomi kodai ir validacijos vis tiek turi būti tikrinami."],["The current frontend stores these preferences but has no background export worker. Enabling a checkbox does not send any invoice.","Dabartinis frontend išsaugo šias parinktis, bet neturi foninės eksporto tarnybos. Varnelės pažymėjimas sąskaitų neišsiunčia."]]),e("payments-persons",["Payment accounts and accountable persons","Apmokėjimo sąskaitos ir atskaitingi asmenys"],"Rivilė GAMA",[11754272],[["Paid-invoice handling needs both accounting accounts and a valid person code when applicable.","Apmokėtos sąskaitos perdavimui reikia apskaitos sąskaitų ir, kai taikoma, tinkamo asmens kodo."],["Export the people list from Cards → 30 Persons through Print → MS Excel, retaining code and name. Match the sales / purchase payment account codes to the receiving chart.","Asmenų sąrašą eksportuokite Kortelės → 30 Asmenys per Spausdinti → MS Excel, palikdami kodą bei vardą ir pavardę. Pardavimų ir pirkimų apmokėjimo sąskaitas sutikrinkite su gavėjo sąskaitų planu."],["FH exposes general payment-account settings and person codes. It does not yet implement a separate payment-account mapping for every person or live payment-document creation.","FH pateikia bendrus apmokėjimo sąskaitų nustatymus ir asmenų kodus. Atskiro kiekvieno asmens apmokėjimo sąskaitų susiejimo bei tikrų mokėjimo dokumentų kūrimo dar nėra."]],"codes"),e("series",["Invoice series","Sąskaitos serija"],"Rivilė GAMA",[5412181],[["Series and invoice number are separate fields.","Serija ir sąskaitos numeris yra atskiri laukai."],["Assign Series in FH when the receiving Rivilė Series field is required. Check it separately from the full document number after import; do not duplicate the prefix in both fields without agreeing the mapping.","FH priskirkite Seriją, kai jos reikia gavėjo Rivilės Serija laukui. Po importo tikrinkite ją atskirai nuo pilno dokumento numerio; be suderintų atitikmenų nedubliuokite priešdėlio abiejuose laukuose."]]),e("missing-person",["Error: person code not found","Klaida: nerastas asmens kodas"],"Rivilė GAMA",[11754227],[["The assigned accountable-person code is missing in Rivilė.","Priskirto atskaitingo asmens kodo nėra Rivilėje."],["Check Cards → 30 Persons. Correct the document mapping or create the actual person with the intended code. The example 24450 is not a mandatory default code.","Patikrinkite Kortelės → 30 Asmenys. Taisykite dokumento atitikmenį arba sukurkite tikrą asmenį su reikiamu kodu. Pavyzdinis 24450 nėra privalomas numatytasis kodas."]],"review"),e("department-company-id",["Error: department ID does not match company ID","Klaida: padalinio ID neatitinka įmonės ID"],"Rivilė GAMA",[14468863],[["This can require a database-identity correction by the Rivilė provider.","Šiai klaidai gali reikėti Rivilės tiekėjo atliekamos bazės identifikatoriaus korekcijos."],["Check that the correct company and database key were selected, then ask the provider to verify the database ID. Do not change invoice values to compensate for an infrastructure mismatch.","Patikrinkite pasirinktą įmonę bei bazės raktą ir paprašykite tiekėjo patikrinti duomenų bazės ID. Nekeiskite sąskaitos reikšmių, kad kompensuotumėte infrastruktūros neatitikimą."]],"review"),e("wrong-import-command",["Error: skip the state / file problem","Klaida: praleiskite būklę / problema su failu"],"Rivilė GAMA",[14525404],[["The wrong import command can produce a file-state error.","Netinkama importo komanda gali sukelti failo būklės klaidą."],["For an actual EIP file use the Rivilė EIP import action (the two-arrow import icon), not another import mode. Verify that the selected file is EIP and not the FH preview XML.","Tikram EIP failui naudokite Rivilės EIP importo veiksmą (dviejų rodyklių importo ikoną), ne kitą importo būdą. Patikrinkite, ar pasirinktas EIP, o ne FH peržiūros XML."]],"review"),e("missing-department",["Error: department 9999999 not found","Klaida: nerastas padalinys 9999999"],"Rivilė GAMA",[3527787],[["A missing or unsuitable department default can cause this error.","Šią klaidą gali sukelti trūkstama arba netinkama padalinio numatytoji reikšmė."],["Check Cards → Departments and Service → Administration → Parameters → SS_PADALINYS. Use a department that exists in this company; do not create the example code blindly.","Patikrinkite Kortelės → Padaliniai ir Servisas → Administravimas → Parametrai → SS_PADALINYS. Naudokite šioje įmonėje egzistuojantį padalinį; pavyzdinio kodo aklai nekurkite."]],"review"),e("invalid-quantity",["Error: I07_KIEKIS_U / 6027 invalid quantity","Klaida: I07_KIEKIS_U / 6027 blogas kiekis"],"Rivilė GAMA",[14655090],[["Quantity precision must agree with the unit and item-card settings.","Kiekio tikslumas turi atitikti vieneto ir prekės kortelės nustatymus."],["Check the unit fraction: 1 allows whole units, 10 one decimal place. Compare the source quantity with the allowed precision and correct the unit setup when appropriate; do not round away a real invoice quantity arbitrarily.","Patikrinkite vieneto frakciją: 1 leidžia sveikus vienetus, 10 – vieną dešimtainį ženklą. Sutikrinkite sąskaitos kiekį su leistinu tikslumu ir prireikus taisykite vieneto nustatymą; savavališkai neapvalinkite tikro kiekio."]],"review"),e("gateway-unavailable",["Error: GAMA database unavailable","Klaida: GAMA duomenų bazė nepasiekiama"],"Rivilė GAMA",[16613110],[["An unavailable Gateway or database is a connection failure, not an invoice-field error.","Nepasiekiamas Gateway ar duomenų bazė yra ryšio, ne sąskaitos lauko klaida."],["Ask the administrator to check the Gateway process and database access. A temporary restart may require several minutes before retrying; verify whether the invoice already exists first.","Paprašykite administratoriaus patikrinti Gateway procesą ir prieigą prie bazės. Po laikino perkrovimo iki pakartojimo gali tekti palaukti kelias minutes; pirmiausia patikrinkite, ar sąskaita jau nesukurta."]],"review"),e("buyer-supplier-type",["Error: customer is not a buyer / supplier","Klaida: klientas nėra pirkėjas / tiekėjas"],"Rivilė GAMA",[18329345],[["The customer card may not allow the invoice direction being imported.","Kliento kortelė gali neleisti importuojamos sąskaitos krypties."],["Check Cards → 02 Customers and its Buyer / Supplier type, then verify the company and VAT codes. Select the correct existing card instead of creating another solely to change its role.","Patikrinkite Kortelės → 02 Klientai ir Pirkėjas / Tiekėjas tipą, tada įmonės bei PVM kodus. Rinkitės tinkamą esamą kortelę, nekurkite kitos vien jos vaidmeniui pakeisti."]],"review"),e("change-customer-code",["Changing a customer code safely","Saugus kliento kodo keitimas"],"Rivilė GAMA",[3507022],[["An established customer code is changed through Rivilė code conversion, not by deleting the card.","Naudojamas kliento kodas keičiamas per Rivilės perkodavimą, ne trinant kortelę."],["Use Service → Statistics → S8 Code changes. Create an operation of type Customer, enter old and new codes, save and post the conversion. Have an authorized administrator verify linked operations and a backup first.","Rinkitės Servisas → Statistika → S8 Kodų keitimas. Sukurkite Klientas tipo operaciją, nurodykite seną bei naują kodą, išsaugokite ir perkelkite perkodavimą. Įgaliotas administratorius prieš tai turi patikrinti susijusias operacijas bei atsarginę kopiją."]],"review"),e("foreign-currency",["Foreign-currency invoices","Valiutinės sąskaitos"],"Rivilė GAMA",[3544888],[["Currency conversion requires receiving-system parameters and available rates.","Valiutos perskaičiavimui reikalingi gavėjo parametrai ir kursai."],["Review Service → Administration → Parameters → SS_VAL_PER for receipts and payments, and enter the needed exchange rates. Check the currency and date on the imported invoice.","Patikrinkite Servisas → Administravimas → Parametrai → SS_VAL_PER įplaukoms bei išmokoms ir suveskite reikalingus valiutų kursus. Importuotoje sąskaitoje sutikrinkite valiutą ir datą."]],"review"),e("code-list",["Copying the Rivilė code list","Rivilės kodų sąrašo perkėlimas"],"Rivilė GAMA",[3565278],[["Export the code list instead of retyping identifiers.","Kodų sąrašą eksportuokite, kad nereikėtų perrašinėti identifikatorių."],["Open Service → Cards → Codes, choose Print and MS Excel. Remove an empty intervening column if present, leaving code and description adjacent. Preserve letter case.","Atverkite Servisas → Kortelės → Kodai, rinkitės Spausdinti ir MS Excel. Jei tarp kodo bei aprašymo yra tuščias stulpelis, jį pašalinkite. Išsaugokite raidžių dydį."]],"codes"),e("customer-list",["Importing the customer list","Klientų sąrašo įkėlimas"],"Rivilė GAMA",[5085970],[["The accounting code and company registration code are separate identifiers.","Apskaitos kodas ir įmonės registracijos kodas yra skirtingi identifikatoriai."],["Export Service → Cards → Customers through Print → MS Excel. Retain accounting code, company code, VAT code and company name in that order.","Servisas → Kortelės → Klientai eksportuokite per Spausdinti → MS Excel. Eilės tvarka palikite apskaitos kodą, įmonės kodą, PVM kodą ir įmonės pavadinimą."],["In FH use organization gear → Counterparties → Import from Excel. Its fifth optional column is IBAN; separate multiple IBANs with commas or semicolons. Check the preview before importing.","FH rinkitės organizacijos dantratį → Kontrahentai → Įkelti iš Excel. Penktas neprivalomas stulpelis yra IBAN; kelis IBAN skirkite kableliu arba kabliataškiu. Prieš įkeldami patikrinkite peržiūrą."]]),e("departments-objects",["Departments and objects","Padaliniai ir objektai"],"Rivilė GAMA",[5086101],[["Department and object lists are maintained separately.","Padalinių ir objektų sąrašai tvarkomi atskirai."],["Open Service → Cards → Departments or Objects. Print to MS Excel and copy the first two data columns. Import them into the matching FH Additional columns directory, not into Expenses.","Atverkite Servisas → Kortelės → Padaliniai arba Objektai. Spausdinkite į MS Excel ir nukopijuokite pirmus du duomenų stulpelius. Įkelkite į atitinkamą FH Papildomų stulpelių registrą, ne į Išlaidas."]],"codes"),e("code-synchronization",["Code synchronization and barcodes","Kodų sinchronizavimas ir barkodai"],"Rivilė GAMA",[8041111],[["API code synchronization is different from invoice export.","Kodų sinchronizavimas per API yra atskiras veiksmas nuo sąskaitų eksporto."],["A connected service can retrieve new / changed codes and alternative barcodes. This requires read access to the corresponding Rivilė directories, not merely a saved export-format name.","Prijungta tarnyba gali gauti naujus ar pakeistus kodus ir alternatyvius barkodus. Tam reikia skaitymo prieigos prie atitinkamų Rivilės registrų, ne vien išsaugoto eksporto formato pavadinimo."],["The current FH gear has manual / Excel code import and per-code alternative values, but no live Refresh from Rivilė action. Use these available controls until that service is implemented.","Dabartiniame FH dantratyje yra rankinis bei Excel kodų įkėlimas ir atskiro kodo alternatyvios reikšmės, bet nėra tikro Atnaujinti iš Rivilės veiksmo. Iki tarnybos įgyvendinimo naudokite esamus valdiklius."]],"codes")];u.Rivilė=y;u["Rivilė API"]=y;u.Pragma4=[...u.Pragma4,u.Pragma3[1]];u["Pragma4 V2"]=u.Pragma4;u["Finvalda Excel"]=u.Finvalda.filter(i=>i.id==="service-codes");u["Debetas Excel"]=[];const C={id:"file-contract",title:["File structure and production compatibility","Failo struktūra ir produkcinis suderinamumas"],description:["Distinguish the FH preview payload from a receiving system’s import specification.","FH peržiūros duomenų atskyrimas nuo gavėjo importo specifikacijos."],sections:[{title:["Current FH export","Dabartinis FH eksportas"],system:"FH",steps:[["The current accounting export uses the schema finansu-harmonija.accounting-export-preview.v1 with importReady=false. Rivilė and Agnum preview profiles produce XML; other configured delivery destinations use JSON. Selecting a format in organization settings does not implement its production serializer.","Dabartinis apskaitos eksportas naudoja finansu-harmonija.accounting-export-preview.v1 schemą su importReady=false. Rivilė ir Agnum peržiūros profiliai pateikia XML, kiti nustatyti perdavimo gavėjai – JSON. Formato pasirinkimas organizacijos nustatymuose neįgyvendina jo produkcinio failo generatoriaus."],["The payload separates destination, company, generation time and documents. A document includes its number, dates, counterparty, currency, net / VAT / total amounts and allocation fields. Accounting allocations and recognized document lines are separate arrays.","Duomenyse atskirti gavėjas, įmonė, generavimo laikas ir dokumentai. Dokumentas apima numerį, datas, kontrahentą, valiutą, sumą be PVM, PVM, bendrą sumą bei paskirstymo laukus. Apskaitiniai paskirstymai ir atpažintos dokumento eilutės pateikiami atskirais masyvais."],["Before production use, agree the receiving schema and validate a sample with its administrator. For CSV / Excel this includes columns, delimiters, encoding, dates and decimal precision; for XML / JSON it includes required fields, nesting and schema version. Never substitute another provider’s API or file contract.","Prieš produkcinį naudojimą su gavėjo administratoriumi suderinkite schemą ir patikrinkite pavyzdį. CSV ar Excel atveju tai stulpeliai, skirtukai, koduotė, datos ir skaičių tikslumas; XML ar JSON – privalomi laukai, struktūra ir schemos versija. Nenaudokite kito tiekėjo API ar failo sutarties kaip FH specifikacijos."],["An iSAF format preference is not a tax submission. Production validation, a compliant file generator and the receiving authority’s acknowledgement are outside the current preview.","iSAF formato parinktis nėra deklaracijos pateikimas. Produkcinė validacija, reikalavimus atitinkantis failo generatorius ir gavėjo patvirtinimas nėra dabartinės peržiūros dalis."]]}]};for(const i of["CSV","Excel","Json","XML","iSAF"])u[i]=[C];const F=[["Check the company, invoice number and direction, currency, net amount, VAT and total against the original. Verify mandatory codes before exporting; a saved code name is not necessarily the destination identifier.","Sutikrinkite įmonę, sąskaitos numerį ir kryptį, valiutą, sumą be PVM, PVM bei bendrą sumą su originalu. Prieš eksportuodami patikrinkite privalomus kodus; išsaugotas pavadinimas nebūtinai yra gavėjo identifikatorius."],["A download, a manual Exported mark and a confirmed external receipt are different events. In a live integration verify the receiving document and its accounting posting separately.","Atsisiuntimas, rankinė Eksportuota žyma ir patvirtintas išorinis gavimas yra skirtingi įvykiai. Tikroje integracijoje gavėjo dokumentą ir jo registravimą apskaitoje tikrinkite atskirai."],["For an uncertain result, search the receiving company by document number and counterparty before repeating. Retry only failed documents after correcting the stated cause; do not resend successful ones with the batch.","Kai rezultatas neaiškus, prieš kartodami gavėjo įmonėje ieškokite pagal dokumento numerį bei kontrahentą. Pašalinę priežastį kartokite tik nepavykusius dokumentus, ne sėkmingą paketo dalį."],["For support, provide the format, company, document number, time and error text without keys, passwords or confidential attachments. If the invoice was digitized incorrectly, use Report issue and the document conversation.","Pagalbai pateikite formatą, įmonę, dokumento numerį, laiką bei klaidos tekstą be raktų, slaptažodžių ar konfidencialių priedų. Jei sąskaita nuskaityta neteisingai, naudokite Pranešti apie klaidą ir dokumento susirašinėjimą."]];function V(i){const a=i.group==="accounting",s=a?P(i.id).map(k=>k.body):i.steps||[],o=a?"export-settings.jpg":["google-drive","sharepoint"].includes(i.id)?`${i.id}.jpg`:void 0,r={id:"configuration",title:a?["Configuration and every field explained","Konfigūravimas ir visų laukų paaiškinimai"]:["Connection settings and collection workflow","Prijungimo nustatymai ir surinkimo eiga"],description:i.summary,fieldReference:!0,sections:[{title:["Where to start","Nuo ko pradėti"],system:"FH",paragraphs:[i.setup],steps:s},...a?[{title:["Directories and additional columns","Registrai ir papildomi stulpeliai"],system:"FH",steps:[["In the organization gear, Counterparties holds company identifiers and accounting codes. Additional columns holds departments, objects, series, centers, accountable persons, product groups and expenses. These lists belong to the selected organization.","Organizacijos dantratyje Kontrahentai saugo įmonių identifikatorius ir apskaitos kodus. Papildomi stulpeliai apima padalinius, objektus, serijas, centrus, atskaitingus asmenis, prekių grupes ir išlaidas. Sąrašai priklauso pasirinktai organizacijai."],["Use New code for one record or Import from Excel to paste code and name separated by TAB. For expense codes choose Code, Service or Product. Review parsed rows before saving; do not import spreadsheet headings as data.","Vienam įrašui rinkitės Naujas kodas, keliems – Įkelti iš Excel ir įklijuokite TAB atskirtus kodą bei pavadinimą. Išlaidoms parinkite Kodas, Paslauga arba Prekė. Prieš išsaugodami patikrinkite peržiūrą; antraščių neįkelkite kaip duomenų."],["Under Additional column settings, Required marks missing values, Default value supplies the configured fallback, and Assign automatically enables that field’s default-assignment rule. Assignment during digitization and during export are separate stages where the selected format supports them.","Papildomų stulpelių nustatymuose Privalomas pažymi trūkstamas reikšmes, Numatytoji reikšmė nurodo atsarginę reikšmę, o Priskirti automatiškai įjungia to lauko numatytosios reikšmės priskyrimą. Skaitmeninimo ir eksportavimo etapai yra atskiri, kai pasirinktas formatas juos palaiko."]]}]:[]],note:a?h:["Only configuration and frontend previews are available. Live authorization, background collection and API-key issuance are not connected. No production account is contacted by this help page.","Veikia konfigūravimas ir frontend peržiūra. Tikra autorizacija, foninis surinkimas bei API rakto išdavimas neprijungti. Šis pagalbos puslapis nesikreipia į produkcinę paskyrą."],...o?{screenshot:{file:o,caption:["Actual Finansų harmonija settings screen; credentials are not shown.","Tikras Finansų harmonijos nustatymų ekranas; prisijungimo duomenys nerodomi."]}}:{}},p={id:"workflow-and-checks",title:a?["Transfer, result and troubleshooting","Perdavimas, rezultatas ir klaidų tikrinimas"]:["Result, access and troubleshooting","Rezultatas, prieiga ir klaidų tikrinimas"],description:i.checks,sections:[{title:["Workflow","Veiksmų eiga"],system:"FH",steps:a?i.method==="api"?A:i.method==="email"?[["UCS StoreHouse v4 exposes a receiving-email setting in FH. Confirm the receiver and required code mappings with its administrator.","FH UCS StoreHouse v4 turi gavėjo el. pašto nustatymą. Su gavėjo administratoriumi patvirtinkite adresą ir reikalingus kodų atitikmenis."],["The current frontend does not send email attachments to the accounting system. Delivery, attachment parsing and posting must each be verified once a secure backend service is connected.","Dabartinis frontend nesiunčia priedų el. paštu į apskaitos sistemą. Prijungus saugią serverio tarnybą, atskirai reikės patikrinti pristatymą, priedo nuskaitymą ir registravimą."]]:S:i.steps||[]},{title:["Checks specific to this integration","Šios integracijos patikrinimai"],system:"FH",paragraphs:[i.checks]},{title:a?["Verify the result before retrying","Patikrinkite rezultatą prieš kartodami"]:["Document processing in FH","Dokumento apdorojimas FH"],system:"FH",steps:a?F:[["When an actual collection service is connected, received files appear in All Documents → Uploaded documents. Review the source details to distinguish the sending email or folder from the assigned organization.","Prijungus tikrą surinkimo tarnybą, gauti failai patenka į Visi dokumentai → Įkelti dokumentai. Šaltinio detalėse atskirkite siuntėjo el. paštą ar aplanką nuo dokumentui priskirtos organizacijos."],["Open the status details for rejected, duplicate, unreadable or unidentified documents. Assign the organization where missing. Processing tasks are reviewed in OCR → Workspace → My tasks or TeamLead; after approval they appear in Documents.","Atverkite atmestų, pasikartojančių, neįskaitomų arba neatpažintos organizacijos dokumentų būsenos detales. Priskirkite trūkstamą organizaciją. Apdorojimo užduotys tikrinamos OCR → Darbo sritis → Mano užduotys arba Komandos vadovas; patvirtintos patenka į Dokumentai."],["A source connection problem and a document validation problem are different. Check access to the configured folder / inbox first, then investigate the individual document. Do not upload the same file repeatedly before checking duplicates.","Šaltinio ryšio ir dokumento validacijos klaidos yra skirtingos. Pirmiausia patikrinkite prieigą prie nurodyto aplanko ar pašto, tada konkretų dokumentą. Neįkelkite to paties failo pakartotinai nepatikrinę dublikatų."]]}],note:a?h:r.note};return[r,p]}const z={id:"invoice-import",sourceArticleIds:[7128078],title:["Exporting invoices from FH and importing into Agnum: totals and quantities","Sąskaitų eksportavimas iš FH ir importavimas į Agnum: suminis ir kiekinis"],description:["Follow the complete route from the processed invoice to XML import, accounting scheme assignment and result verification in Agnum.","Visa eiga nuo suskaitmenintos sąskaitos iki XML importo, apskaitos schemos priskyrimo ir rezultato patikrinimo Agnum."],sections:[{title:["1. Choose totals or quantity import","1. Pasirinkite suminį arba kiekinį importą"],system:"Agnum",paragraphs:[["Both purchase and sales invoices can be imported. Choose the method according to the detail needed in accounting, not merely according to how many lines the PDF contains.","Galima importuoti tiek pirkimo, tiek pardavimo sąskaitas. Būdą pasirinkite pagal apskaitoje reikalingą detalumą, ne vien pagal PDF matomų eilučių skaičių."]],table:{headers:[["Method","Būdas"],["What is transferred","Kas perkeliama"],["Agnum checkbox","Agnum varnelė"]],rows:[[["Totals","Suminis"],["Invoice totals; the accounting scheme is selected in Agnum.","Sąskaitos sumos; apskaitos schema parenkama Agnum."],["Importuoti sumine išraiška: checked","Importuoti sumine išraiška: pažymėta"]],[["Quantities / lines","Kiekinis / su eilutėmis"],["Digitized lines, quantities and assigned product / service codes.","Suskaitmenintos eilutės, kiekiai ir priskirti prekių / paslaugų kodai."],["Importuoti sumine išraiška: unchecked","Importuoti sumine išraiška: nepažymėta"]]]},example:{title:["Example: the same invoice, two methods","Pavyzdys: ta pati sąskaita, du būdai"],paragraphs:[["Invoice AG-2026-001 contains 2 items at EUR 50 and 1 service at EUR 100. Net amount: EUR 200; VAT at 21%: EUR 42; total: EUR 242.","Sąskaitoje AG-2026-001 yra 2 prekės po 50 EUR ir 1 paslauga už 100 EUR. Be PVM – 200 EUR; 21 % PVM – 42 EUR; iš viso – 242 EUR."],["Totals import uses these invoice amounts. Quantity import must also preserve both lines: product code, quantity 2, unit price 50; service code, quantity 1, unit price 100. The invoice total remains EUR 242 in either method.","Suminis importas naudoja sąskaitos sumas. Kiekinis papildomai išsaugo abi eilutes: prekės kodą, kiekį 2, kainą 50; paslaugos kodą, kiekį 1, kainą 100. Abiem būdais bendra sąskaitos suma lieka 242 EUR."]]}},{title:["2. Check the invoice and codes in FH","2. Patikrinkite sąskaitą ir kodus FH"],system:"FH",steps:[["Open All Documents → Documents and select the organization whose accounting you are managing. The invoice must have completed OCR processing and have no unresolved issue blocking export.","Atverkite Visi dokumentai → Dokumentai ir pasirinkite organizaciją, kurios apskaitą tvarkote. Sąskaita turi būti apdorota OCR, be neišspręstos klaidos, blokuojančios eksportą."],["Open the organization gear → Documents & digitization setup. Select Agnum. Review the item account code and registration-number option; save the settings for this organization.","Atverkite organizacijos dantratį → Dokumentų ir skaitmeninimo nustatymai. Pasirinkite Agnum. Patikrinkite prekės sąskaitos kodą bei registracijos numerio parinktį ir išsaugokite šios organizacijos nustatymus."],["In the document check purchase / sale direction, number, dates, counterparty, currency and all three amounts against the original. Select the VAT classifier that corresponds to the transaction.","Dokumente sutikrinkite pirkimo / pardavimo kryptį, numerį, datas, kontrahentą, valiutą ir visas tris sumas su originalu. Pasirinkite operacijai tinkantį PVM klasifikatorių."],["For quantity import, review every digitized line and assign the receiving product or service code in Expense. Import the code directory first if the required values are missing.","Kiekiniam importui peržiūrėkite kiekvieną suskaitmenintą eilutę ir lauke Išlaida priskirkite gavėjo prekės arba paslaugos kodą. Jei pasirinkimų nėra, pirmiausia įkelkite kodų sąrašą."],["Where applicable, check warehouse, group and object. FH exposes document / line warehouse defaults in Additional column settings; it does not yet have a separate Agnum warehouse picker on every document.","Kai taikoma, patikrinkite sandėlį, grupę ir objektą. FH Papildomų stulpelių nustatymuose pateikia dokumento / eilutės sandėlio numatytąsias reikšmes; atskiro Agnum sandėlio pasirinkimo kiekviename dokumente dar nėra."]],links:[{topic:"item-codes",label:["How to import product and service codes from Agnum","Kaip iš Agnum įkelti prekių ir paslaugų kodus"]},{topic:"warehouses",label:["Where to find and enter warehouse codes","Kur rasti ir įrašyti sandėlių kodus"]},{topic:"configuration",label:["Agnum settings and field descriptions","Agnum nustatymai ir laukų paaiškinimai"]}]},{title:["3. Export the selected invoices and unpack the files","3. Eksportuokite pažymėtas sąskaitas ir išskleiskite failus"],system:"FH",steps:[["Mark the required invoices in Documents. Use Export selected documents and select Agnum. File download is separate from Send to accounting.","Dokumentų sąraše varnelėmis pažymėkite reikiamas sąskaitas. Rinkitės Eksportuoti pažymėtus dokumentus ir Agnum. Failo atsisiuntimas yra atskiras nuo Siųsti į apskaitos sistemą."],["For a real Agnum import you need compatible invoice XML. The current FH export is a preview with importReady=false, not an import-certified Agnum file. Use the following Agnum steps only with a validated production file.","Tikram Agnum importui reikia suderinamo sąskaitų XML. Dabartinis FH eksportas yra peržiūra su importReady=false, ne importui patvirtintas Agnum failas. Toliau aprašytus Agnum veiksmus atlikite tik su patikrintu produkciniu failu."],["If the validated export arrives as ZIP, unpack it first: Windows → right-click → Extract all; macOS → double-click the ZIP. Open the extracted folder, not the archive itself.","Jei patikrintas eksportas pateiktas ZIP archyvu, pirmiausia jį išskleiskite: Windows → dešinysis pelės mygtukas → Išskleisti viską; macOS → dukart spustelėkite ZIP. Atverkite išskleistą aplanką, ne patį archyvą."],["Keep purchase and sales files separate. Select the purchase XML in the purchase import and the sales XML in the sales import. Renaming a JSON or ZIP extension to XML does not convert its contents.","Pirkimų ir pardavimų failus atskirkite. Pirkimų importe rinkitės pirkimų XML, pardavimų importe – pardavimų XML. JSON ar ZIP plėtinio pakeitimas į XML duomenų nekonvertuoja."]]},{title:["4. Import purchase invoices in Agnum","4. Importuokite pirkimo sąskaitas į Agnum"],system:"Agnum",steps:[["In the intended Agnum company open Dokumentai → Pajamavimai → Atidėjimai → Importas iš XML.","Reikiamoje Agnum įmonėje atverkite Dokumentai → Pajamavimai → Atidėjimai → Importas iš XML."],["For totals import, check Importuoti sumine išraiška. For detailed quantities and item lines, leave this option unchecked.","Suminėms sąskaitoms pažymėkite Importuoti sumine išraiška. Jei importuojate kiekius ir prekių eilutes, varnelę nuimkite."],["Select the extracted purchase XML file and click Nuskaityti failą. Review the loaded invoice numbers, quantities and amounts.","Pasirinkite išskleistą pirkimų XML failą ir spauskite Nuskaityti failą. Peržiūrėkite nuskaitytus sąskaitų numerius, kiekius ir sumas."],["Use Patikrinti and Importuoti, or the combined Patikrinti ir importuoti action. If validation reports errors, resolve them before importing again.","Rinkitės Patikrinti ir Importuoti arba bendrą Patikrinti ir importuoti veiksmą. Jei tikrinimas nurodo klaidų, pašalinkite jas prieš pakartotinį importą."]],links:[{topic:"duplicate-control",label:["Check for an existing invoice before repeating the import","Kaip patikrinti dublikatą prieš kartojant importą"]}]},{title:["5. Import sales invoices in Agnum","5. Importuokite pardavimo sąskaitas į Agnum"],system:"Agnum",steps:[["Open Dokumentai → Pardavimai → Išankstinės sąskaitos → Importas iš XML in the same intended company.","Reikiamoje įmonėje atverkite Dokumentai → Pardavimai → Išankstinės sąskaitos → Importas iš XML."],["Check Importuoti sumine išraiška for summarized invoices; uncheck it when importing item quantities and lines.","Suminėms sąskaitoms pažymėkite Importuoti sumine išraiška; importuojant kiekius ir eilutes – nuimkite."],["Choose the sales XML, then Nuskaityti failą. Do not select the purchase file simply because the invoice numbers look similar.","Pasirinkite pardavimų XML ir spauskite Nuskaityti failą. Nesirinkite pirkimų failo vien todėl, kad sąskaitų numeriai panašūs."],["Run Patikrinti and Importuoti, or Patikrinti ir importuoti. Check the result for each imported document, not just whether the dialog closed.","Vykdykite Patikrinti ir Importuoti arba Patikrinti ir importuoti. Patikrinkite kiekvieno dokumento rezultatą, ne vien tai, ar užsidarė langas."]]},{title:["6. Assign a scheme and post one invoice","6. Priskirkite schemą ir perkelkite vieną sąskaitą"],system:"Agnum",paragraphs:[["Import and posting are two different steps. In the deferred-document list, set the date filter to include the imported invoices before searching for them.","Importas ir perkėlimas į apskaitą – du skirtingi veiksmai. Atidėtų dokumentų sąraše nustatykite laikotarpį, apimantį importuotas sąskaitas."]],steps:[["Open the invoice in the deferred-document list and check its number and counterparty.","Atidėtų dokumentų sąraše atverkite sąskaitą ir sutikrinkite jos numerį bei kontrahentą."],["Select the accounting scheme appropriate to that transaction. A purchase scheme should not be reused for an unrelated sales transaction.","Pasirinkite tai operacijai tinkamą apskaitos schemą. Pirkimo schemos netaikykite nesusijusiai pardavimo operacijai."],["Check Perkelti, then click Išsaugoti. Check the resulting accounting entry in Agnum.","Pažymėkite Perkelti ir spauskite Išsaugoti. Agnum patikrinkite sukurtą apskaitos įrašą."]]},{title:["7. Assign a scheme to multiple invoices","7. Priskirkite schemą kelioms sąskaitoms"],system:"Agnum",steps:[["In Agnum open the gear in the top toolbar and choose Atidėtų dokumentų perkėlimas.","Viršutinėje Agnum juostoje paspauskite dantratį ir pasirinkite Atidėtų dokumentų perkėlimas."],["Enable Automatiškai perkelti pagal schemą and choose the scheme to apply. Check the applicable documents and period before starting.","Pažymėkite Automatiškai perkelti pagal schemą ir pasirinkite taikomą schemą. Prieš pradėdami patikrinkite apimamų dokumentų ir laikotarpio pasirinkimą."],["Click Pradėti. Review the posting result and handle rejected documents individually; do not assume every invoice succeeded.","Spauskite Pradėti. Peržiūrėkite perkėlimo rezultatą, o atmestus dokumentus tikrinkite atskirai – nelaikykite visų sąskaitų sėkmingai perkeltomis."]]},{title:["8. Verify the final result","8. Patikrinkite galutinį rezultatą"],system:"Agnum",steps:[["Search by invoice number and counterparty. Compare net, VAT and total amounts and currency with the original; for quantities, also compare each code, quantity and price.","Ieškokite pagal sąskaitos numerį ir kontrahentą. Su originalu sutikrinkite sumą be PVM, PVM, bendrą sumą ir valiutą; kiekiniu atveju – dar kiekvieną kodą, kiekį ir kainą."],["Confirm that the intended scheme was applied and the document was posted. A downloaded XML or an FH Exported label alone does not confirm Agnum posting.","Įsitikinkite, kad pritaikyta tinkama schema ir dokumentas perkeltas. Vien atsisiųstas XML ar FH žyma Eksportuota Agnum perkėlimo nepatvirtina."],["For AG-2026-001 in the example, the final total must remain EUR 242. If an import result is uncertain, look for this invoice before another attempt to avoid a duplicate.","Pavyzdžio AG-2026-001 galutinė suma turi likti 242 EUR. Jei importo rezultatas neaiškus, prieš kartodami ieškokite šios sąskaitos, kad nesukurtumėte dublikato."]],links:[{topic:"workflow-and-checks",label:["Export result, errors and safe retry","Eksporto rezultatas, klaidos ir saugus pakartojimas"]},{topic:"duplicate-control",label:["Agnum duplicate control","Agnum dublikatų kontrolė"]}]}],note:["FH currently provides export settings and a file preview, not a verified production Agnum adapter. These instructions distinguish the current FH interface from the Agnum procedure for a compatible production XML.","Dabartinėje FH versijoje yra eksporto nustatymai ir failo peržiūra, bet ne patikrintas produkcinis Agnum adapteris. Instrukcijoje atskirta dabartinė FH sąsaja ir Agnum eiga su suderinamu produkciniu XML."],screenshot:{file:"export-agnum.jpg",caption:["FH organization export settings with Agnum selected.","FH organizacijos eksporto nustatymai pasirinkus Agnum."]}},O=[{title:["1. Understand the connection","1. Kaip veikia ryšys"],system:"Rivilė GAMA",paragraphs:[["In a connected installation, the FH server adapter sends a request to Rivilė API. Manorivile-Gateway provides the route to the configured GAMA database. An API key authorizes access; it does not install the Gateway or select a database by guessing its name.","Prijungtoje sistemoje FH serverio adapteris siunčia užklausą į Rivilė API. Manorivile-Gateway perduoda ją sukonfigūruotai GAMA duomenų bazei. API raktas leidžia autorizuoti prieigą, bet neįdiegia Gateway ir neatspėja reikiamos bazės."]],table:{headers:[["Component","Dalis"],["Purpose","Kam skirta"],["Who verifies it","Kas patikrina"]],rows:[[["API service and key","API paslauga ir raktas"],["Access granted for the intended integration.","Suteikta prieiga reikiamai integracijai."],["Rivilė representative / administrator.","Rivilės atstovas / administratorius."]],[["Gateway","Gateway"],["A running service that can reach GAMA.","Veikianti tarnyba, pasiekianti GAMA."],["The server administrator.","Serverio administratorius."]],[["Database","Duomenų bazė"],["The company that receives the invoice.","Įmonė, į kurią patenka sąskaita."],["Administrator together with the accountant.","Administratorius kartu su buhalteriu."]],[["FH codes","FH kodai"],["Supplier, item, VAT and allocation references.","Tiekėjo, prekės, PVM ir paskirstymo atitikmenys."],["The accountant.","Buhalteris."]]]}},{title:["2. Enable access on the Rivilė side","2. Prieiga Rivilės pusėje"],system:"Rivilė GAMA",steps:[["Arrange the API service with Rivilė or its representative. Confirm the intended company, database name, base currency and database technology; use the identifiers from your installation, not example values.","Su Rivile ar jos atstovu suderinkite API paslaugą. Patvirtinkite įmonę, duomenų bazės vardą, bazinę valiutą bei bazės technologiją; naudokite savo diegimo identifikatorius, ne pavyzdines reikšmes."],["The administrator installs Gateway on a computer with access to the database and configures its connection. They verify that the service is running and the required network routes are available. The accountant does not enter database credentials into a help page.","Administratorius įdiegia Gateway kompiuteryje, pasiekiančiame bazę, ir sukonfigūruoja ryšį. Jis patikrina, ar tarnyba veikia ir tinklo ryšys leidžiamas. Buhalteris duomenų bazės prisijungimų į pagalbos puslapį neveda."],["Use a separate key for the integration where possible. Keep secrets in the connected server’s approved secret storage, not in email, screenshots, invoice notes or copied spreadsheets.","Integracijai naudokite atskirą raktą. Slaptus duomenis laikykite prijungto serverio patvirtintoje saugykloje, ne laiškuose, ekrano nuotraukose, sąskaitos pastaboje ar skaičiuoklėje."]]},{title:["3. Select the matching FH organization and codes","3. FH pasirinkite įmonę ir kodus"],system:"FH",steps:[["Open All Documents → Documents → select the organization → gear → Documents & digitization setup. Select Rivilė API, not the Rivilė file format or Rivilė ERP.","Atverkite Visi dokumentai → Dokumentai → pasirinkite organizaciją → dantratis → Dokumentų ir skaitmeninimo nustatymai. Rinkitės Rivilė API, ne Rivilė failo formatą ir ne Rivilė ERP."],["Confirm the displayed database belongs to this company. The database name is an identifier, not an API key. This frontend does not validate a real secret or connect to Gateway; use non-secret placeholders when reviewing the form.","Patikrinkite, ar rodoma duomenų bazė priklauso šiai įmonei. Bazės vardas yra identifikatorius, ne API raktas. Šis frontend netikrina tikro rakto ir nejungiasi prie Gateway; formos peržiūrai naudokite ne slaptus vietaženklius."],["Load the company’s customer and item / service codes, then assign the document VAT and required dimensions. A successful connection does not supply missing invoice allocations.","Įkelkite šios įmonės klientų bei prekių / paslaugų kodus, dokumentui priskirkite PVM ir privalomas dimensijas. Veikiantis ryšys neužpildo trūkstamo sąskaitos paskirstymo."],["Review automatic posting separately from automatic export. Keep these choices deliberate: the receiving system can create a document before it is posted to accounting.","Atskirai peržiūrėkite automatinį perkėlimą ir automatinį eksportą. Parinktis nustatykite sąmoningai: gavėjo sistemoje dokumentas gali būti sukurtas dar neperkeltas į apskaitą."]],links:[{topic:"configuration",label:["All Rivilė API settings explained","Visų Rivilė API nustatymų paaiškinimai"]},{topic:"code-list",label:["Import item and expense codes","Prekių ir išlaidų kodų įkėlimas"]},{topic:"customer-list",label:["Import customer identifiers","Klientų identifikatorių įkėlimas"]},{topic:"automatic-export",label:["Automatic export and posting","Automatinis eksportas ir perkėlimas"]}]},{title:["4. Read the response before retrying","4. Prieš kartodami perskaitykite atsakymą"],system:"Rivilė GAMA",paragraphs:[["In a production integration, inspect both the HTTP result and any document / line error in the response. A connection error and an invalid invoice require different corrections.","Produkciniame perdavime tikrinkite HTTP rezultatą ir atsakyme pateiktą dokumento ar eilutės klaidą. Ryšio gedimas ir netinkami sąskaitos duomenys taisomi skirtingai."]],table:{headers:[["Result","Rezultatas"],["Meaning","Reikšmė"],["Next check","Ką tikrinti"]],rows:[[["401","401"],["Authorization was rejected.","Prieiga nepatvirtinta."],["Key, expiry and API address; do not change invoice amounts.","Raktą, jo galiojimą ir API adresą; nekeisti sąskaitos sumų."]],[["502","502"],["Gateway connection problem.","Gateway ryšio problema."],["Service and connectivity with the administrator.","Tarnybą bei ryšį su administratoriumi."]],[["504 / timeout","504 / laukimo laiko pabaiga"],["The reply did not arrive in time.","Atsakymas negautas laiku."],["Look for the invoice in GAMA before another attempt.","Prieš kartojant ieškoti sąskaitos GAMA."]],[["207 / partial result","207 / dalinis rezultatas"],["Some operations or lines need review.","Reikia patikrinti dalį operacijų ar eilučių."],["Identify the failed part; do not resend successful documents.","Nustatyti nepavykusią dalį; nekartoti sėkmingų dokumentų."]],[["Document validation error","Dokumento duomenų klaida"],["The receiver rejected a field or reference.","Gavėjas atmetė lauką arba atitikmenį."],["The exact person, department, quantity or other reported field.","Tikslų nurodytą asmenį, padalinį, kiekį ar kitą lauką."]]]},links:[{topic:"gateway-unavailable",label:["Gateway unavailable: checks","Kai Gateway nepasiekiamas"]},{topic:"missing-person",label:["Missing person code","Kai nerastas asmens kodas"]},{topic:"invalid-quantity",label:["Invalid quantity","Kai netinkamas kiekis"]}]},{title:["5. Verify a single invoice end to end","5. Patikrinkite vieną sąskaitą nuo pradžios iki galo"],system:"FH",steps:[["Once a production adapter is connected, choose one invoice with verified supplier, lines and VAT. Send it once and retain its response / receiving identifier.","Prijungus produkcinį adapterį pasirinkite vieną sąskaitą su patikrintu tiekėju, eilutėmis bei PVM. Siųskite vieną kartą ir išsaugokite atsakymą / gavėjo identifikatorių."],["In GAMA search the intended company by document number and counterparty. Compare direction, dates, currency, net, VAT and total; verify whether posting occurred as intended.","GAMA reikiamoje įmonėje ieškokite pagal numerį ir kontrahentą. Sutikrinkite kryptį, datas, valiutą, sumą be PVM, PVM bei bendrą sumą; patikrinkite, ar perkėlimas įvyko taip, kaip nustatyta."],["Only after a successful comparison apply the same configuration to a batch. A success label in the current frontend is not a real GAMA receipt.","Tik sėkmingai sutikrinę taikykite tuos pačius nustatymus paketui. Dabartinio frontend sėkmės žyma nėra tikras GAMA gavimo patvirtinimas."]]}],N={title:["Example: two codes pasted from Excel","Pavyzdys: du iš Excel įklijuoti kodai"],code:`00015	Office supplies
S-002	Accounting service`,paragraphs:[["The gap between the code and name is a TAB. Both codes are text: keep the zeros in 00015. The examples are not real accounting codes; replace them with values from your receiving company.","Tarp kodo ir pavadinimo yra TAB. Abu kodai – tekstas: išsaugokite 00015 pradžios nulius. Tai ne tikri apskaitos kodai – naudokite savo gavėjo įmonės reikšmes."],["In the import preview expect two rows, not one long value. After import, select the correct code and type on the invoice. Importing this directory does not automatically assign it to previously saved invoices.","Įkėlimo peržiūroje turi būti dvi eilutės, ne viena ilga reikšmė. Įkėlę sąskaitoje pasirinkite tinkamą kodą bei tipą. Registro įkėlimas savaime nepriskiria kodų anksčiau išsaugotoms sąskaitoms."]]},H=(i,...a)=>({title:i,paragraphs:a}),U=["Worked example","Praktinis pavyzdys"],L={Agnum:["For a EUR 242 invoice (net 200 + VAT 42), choose totals for a scheme-based import or quantities to retain item codes. Both methods must preserve the same total.","242 EUR sąskaitai (200 be PVM + 42 PVM) rinkitės suminį importą su schema arba kiekinį su prekių kodais. Abiem būdais bendra suma turi sutapti."],Apskaita5:["For invoice P-001, select the actual service code and VAT classifier from the receiving company. A label such as Office supplies is not a substitute for the catalog identifier.","Sąskaitai P-001 pasirinkite gavėjo įmonės paslaugos kodą ir PVM klasifikatorių. Pavadinimas Kanceliarinės prekės nepakeičia katalogo identifikatoriaus."],BSS:["A spreadsheet has Document No., Date and Amount columns. Select a BSS template mapped to those columns. Loading a different template can place the amount in the wrong field even if the file opens.","Skaičiuoklėje yra Dokumento Nr., Data ir Suma. Rinkitės šiems stulpeliams pritaikytą BSS šabloną. Kitas šablonas gali sumą priskirti netinkamam laukui, nors failas atsidaro."],"BSS Api":["If the server belongs to environment A, the environment ID and company ID must also belong to A. An API v2 password is not the same setting as the original API key.","Jei serveris priklauso aplinkai A, aplinkos ID bei įmonės ID taip pat turi būti iš A. API v2 slaptažodis nėra tas pats nustatymas kaip pirmos versijos API raktas."],"Business Central":["Use placeholders when discussing configuration: https://login.microsoftonline.com/{tenant}/oauth2/v2.0/token. The invoice endpoint must reference the same tenant, environment and company, plus the installed invoice extension.","Aptariant konfigūraciją naudokite vietaženklius: https://login.microsoftonline.com/{tenant}/oauth2/v2.0/token. Sąskaitų adresas turi nurodyti tą patį nuomininką, aplinką, įmonę ir įdiegtą sąskaitų plėtinį."],Būtent:["An invoice has a positive EUR 100 line and a EUR −10 discount line. Before enabling Ignore non-positive amounts, check that the discount is not lost and the actual EUR 90 net total is preserved.","Sąskaitoje yra 100 EUR eilutė ir −10 EUR nuolaidos eilutė. Prieš įjungdami neteigiamų sumų praleidimą patikrinkite, kad nuolaida nedingtų ir liktų faktinė 90 EUR suma be PVM."],"Būtent kiekinis":["Two items at EUR 50 must retain quantity 2 and unit price 50. Replacing the line with quantity 1 at EUR 100 preserves the total but changes stock quantities.","Dvi prekės po 50 EUR turi išlaikyti kiekį 2 ir kainą 50. Pakeitus į kiekį 1 ir kainą 100 suma sutaps, bet pasikeis sandėlio kiekis."],Centas:["If a EUR invoice imports but a USD invoice fails, inspect the USD currency and invoice-date rate in Centas before changing the invoice. Do not replace USD with EUR to bypass the error.","Jei EUR sąskaita priimama, o USD – ne, Centas patikrinkite USD valiutą ir sąskaitos datos kursą. Nekeiskite USD į EUR vien tam, kad apeitumėte klaidą."],CSV:["Code 00015 must remain text; 2026-11-20 must remain the invoice date. Agree whether 121.00 is written with a dot or comma and whether the file separator is a comma, semicolon or TAB.","Kodas 00015 turi likti tekstas, o 2026-11-20 – sąskaitos data. Suderinkite, ar 121,00 rašoma su kableliu ar tašku ir ar failo skirtukas – kablelis, kabliataškis ar TAB."],Debetas:["Branch A and expense article IT are different dimensions. Put each receiving code in its corresponding field; entering the branch name in the expense field does not create a mapping.","Filialas A ir išlaidų straipsnis IT yra skirtingos dimensijos. Kiekvieną gavėjo kodą įrašykite jo lauke; filialo pavadinimas išlaidų lauke atitikmens nesukuria."],"Debetas Excel":["If the receiving template expects expense code before VAT classifier, keep that order. The generic Excel option and Debetas Excel are not interchangeable just because both use spreadsheet software.","Jei gavėjo šablone išlaidų kodas yra prieš PVM klasifikatorių, išlaikykite tokią tvarką. Bendras Excel ir Debetas Excel nėra tapatūs vien todėl, kad abu naudojami skaičiuoklėje."],Dineta:["Use the purchase GL template for P-001 and the sales template for S-001. A working server address cannot correct a template or warehouse belonging to another company.","P-001 taikykite pirkimų DK šabloną, S-001 – pardavimų. Veikiantis serverio adresas neištaiso kitai įmonei priklausančio šablono ar sandėlio kodo."],Directo:["A purchase key may be valid while sales access is absent. Check the key for the actual direction; do not paste the purchase key into both fields without provider confirmation.","Pirkimų raktas gali galioti, nors pardavimų prieigos nėra. Tikrinkite konkrečios krypties raktą; be tiekėjo patvirtinimo nedėkite pirkimų rakto į abu laukus."],Euroskaita:["When a document has type SERVICE and warehouse MAIN, confirm both identifiers in the receiving company. An invoice type name displayed in FH does not automatically define a Euroskaita operation code.","Kai dokumento tipas SERVICE, o sandėlis MAIN, patvirtinkite abu identifikatorius gavėjo įmonėje. FH rodomas tipo pavadinimas automatiškai neapibrėžia Euroskaita operacijos kodo."],Excel:["Before import, compare one row: invoice P-001, net 100, VAT 21, total 121 EUR. If the receiver combines net and VAT into one field, fix the column mapping rather than changing the invoice values.","Prieš importą sutikrinkite vieną eilutę: P-001, be PVM 100, PVM 21, iš viso 121 EUR. Jei gavėjas sumą ir PVM priskiria vienam laukui, taisykite stulpelių atitikmenis, ne sąskaitos reikšmes."],Finvalda:["A saved service code and a warehouse code must exist in the selected Finvalda company. Check the VA import parameters when the correct invoice arrives with an incorrect department or employee.","Paslaugos ir sandėlio kodai turi egzistuoti pasirinktoje Finvalda įmonėje. Jei teisinga sąskaita gauna netinkamą padalinį ar darbuotoją, tikrinkite VA importo parametrus."],"Finvalda Excel":["Use a small spreadsheet with one purchase and one sale to verify type, expense and VAT columns. A file intended for the regular Finvalda importer is not automatically the Excel template.","Vienos pirkimo ir vienos pardavimo sąskaitos skaičiuokle patikrinkite tipo, išlaidų bei PVM stulpelius. Įprastam Finvalda importui skirtas failas savaime nėra Excel šablonas."],iSAF:["A sales invoice and a purchase invoice may both total EUR 121 but belong to different registers. Preserve direction, VAT classifier and document facts; exporting a preview does not submit either register.","Pardavimo ir pirkimo sąskaitos gali abi būti po 121 EUR, bet priklausyti skirtingiems registrams. Išlaikykite kryptį, PVM klasifikatorių ir faktinius duomenis; peržiūros eksportas registro nepateikia."],Json:["Treat invoice number 00015 as a string, not the number 15. Keep recognized lines separate from accounting allocations. A JSON filename is not an API endpoint or a transmission receipt.","Sąskaitos numerį 00015 laikykite tekstu, ne skaičiumi 15. Atpažintas eilutes atskirkite nuo apskaitinių paskirstymų. JSON failo pavadinimas nėra API adresas ar perdavimo patvirtinimas."],Lobasoft:["For P-001, record the recipient-required expense and VAT codes, then compare one exported document with the agreed Lobasoft sample. Without that sample, do not assume generic JSON is importable.","P-001 priskirkite gavėjui reikalingus išlaidų bei PVM kodus ir palyginkite eksportą su suderintu Lobasoft pavyzdžiu. Neturint pavyzdžio negalima laikyti bendro JSON tinkamu importui."],Monet:["Use the identification code for company A together with company A correspondence codes. A code copied from company B can refer to a different integration even if both companies use Monet.","Įmonės A identifikavimo kodą naudokite su įmonės A korespondencijos kodais. Iš įmonės B nukopijuota reikšmė gali nurodyti kitą integraciją, nors abi naudoja Monet."],Odoo:["An API URL must correspond to the agreed invoice adapter. Check the company, default product and payable account before sending a purchase; an ordinary Odoo login URL does not define that adapter.","API adresas turi atitikti suderintą sąskaitų adapterį. Prieš pirkimo perdavimą patikrinkite įmonę, numatytąją prekę ir mokėtinų sumų sąskaitą; įprastas Odoo prisijungimo adresas adapterio neapibrėžia."],Optimum:["For a service invoice, match the Service type to the receiving card. If Account.AccountId is empty, inspect the actual input VAT account; do not substitute a random GL code.","Paslaugos sąskaitoje Paslaugos tipą suderinkite su gavėjo kortele. Jei Account.AccountId tuščias, tikrinkite tikrą gautino PVM sąskaitą, neįrašykite atsitiktinio DK kodo."],Paulita:["Export one purchase P-001 with its assigned expense code and compare the receiving totals with the original. Before a larger batch, confirm the XML specification accepted by your Paulita version.","Eksportuokite vieną pirkimą P-001 su išlaidų kodu ir sutikrinkite gavėjo sumas su originalu. Prieš didesnį paketą patvirtinkite jūsų Paulita versijai tinkamą XML specifikaciją."],Pragma3:["Check an ordinary invoice and a credit invoice separately. A direction-switch setting changes how the credit is represented; do not enable it solely to remove a minus sign from the original.","Atskirai patikrinkite įprastą ir kreditinę sąskaitą. Krypties pakeitimo nustatymas keičia kredito pateikimą; neįjunkite jo vien tam, kad panaikintumėte originale esantį minusą."],Pragma4:["A supplier exists under accounting code T-015 but the document carries a company registration code. Resolve the supplier mapping instead of creating a duplicate card with the same name.","Tiekėjas egzistuoja apskaitos kodu T-015, o dokumente yra įmonės registracijos kodas. Suderinkite tiekėjo atitikmenį, nekurkite kitos kortelės tokiu pačiu pavadinimu."],"Pragma4 V2":["If the receiver requests V2, test with that exact template. Matching totals in a Pragma4 preview do not prove that its structure also fits Pragma4 V2.","Jei gavėjui reikia V2, tikrinkite būtent tą šabloną. Sutampančios Pragma4 peržiūros sumos neįrodo, kad jos struktūra tinka Pragma4 V2."],Rivilė:["For a purchase with a new supplier and product, the compatible production package is imported in dependency order: client, product, then purchase. Do not import only the last file.","Pirkimui su nauju tiekėju ir preke suderinamas produkcinis paketas importuojamas pagal priklausomybes: klientas, prekė, tada pirkimas. Neįkelkite vien paskutinio failo."],"Rivilė API":["Creating a document and posting it are separate outcomes. If automatic posting is disabled, a successfully created invoice still needs the agreed posting step in Rivilė.","Dokumento sukūrimas ir perkėlimas – atskiri rezultatai. Jei automatinis perkėlimas išjungtas, sukurtai sąskaitai vis dar reikia sutarto perkėlimo veiksmo Rivilėje."],"Rivilė ERP":["Use the ERP company key and ERP item codes. GAMA Gateway credentials and a similarly named GAMA product are not interchangeable with ERP identifiers.","Naudokite ERP įmonės raktą ir ERP prekių kodus. GAMA Gateway prisijungimai bei panašiai pavadinta GAMA prekė nėra tapatūs ERP identifikatoriams."],Roda:["A document may need both department ADMIN and project P-01. Check them as separate dimensions, then compare the file against the receiving Roda import definition.","Dokumentui gali reikėti padalinio ADMIN ir projekto P-01. Tikrinkite juos kaip atskiras dimensijas, tada palyginkite failą su gavėjo Roda importo aprašu."],Saikas:["For a purchase of EUR 100 + VAT 21, check the purchase account and purchase VAT account separately. The corresponding sales mappings must not be used simply because the totals match.","100 EUR + 21 EUR PVM pirkimui atskirai tikrinkite pirkimų bei pirkimų PVM sąskaitas. Pardavimų atitikmenys netinka vien todėl, kad sumos vienodos."],"Site.pro":["If stock was received on 20 November but the sale is dated 19 November, inspect the receiving stock records and original dates. Do not change the invoice date merely to remove a stock error.","Jei atsargos gautos lapkričio 20 d., o pardavimo data – 19 d., tikrinkite gavėjo atsargų įrašus ir pirmines datas. Nekeiskite sąskaitos datos vien tam, kad dingtų sandėlio klaida."],StandardERP:["Confirm whether the receiving import expects an item code and warehouse on each line. A generic file with a total of EUR 121 is not sufficient evidence that the stock allocation is correct.","Patvirtinkite, ar gavėjo importas tikisi prekės ir sandėlio kodo kiekvienoje eilutėje. Bendras failas su 121 EUR suma neįrodo, kad atsargų paskirstymas teisingas."],Syrve:["For 4 packages containing 0.5 kg each, the stock quantity is 2 kg. Verify the unit conversion and SKU, but keep the invoice total unchanged.","Jei yra 4 pakuotės po 0,5 kg, atsargų kiekis – 2 kg. Tikrinkite vienetų santykį ir SKU, bet nekeiskite sąskaitos bendros sumos."],"UCS StoreHouse v4":["The receiving email address and stock codes serve different purposes. Confirm both the mailbox for delivery and the recipient-compatible attachment structure before configuring automatic delivery.","Gavėjo el. paštas ir atsargų kodai atlieka skirtingas funkcijas. Prieš automatinį siuntimą patvirtinkite ir pašto dėžutę, ir gavėjui tinkamą priedo struktūrą."],Uniconta:["Check that the configured API URL and key refer to the intended company. A valid login does not establish which expense or VAT code should be used for P-001.","Patikrinkite, ar API adresas bei raktas skirti reikiamai įmonei. Galiojantis prisijungimas nenustato, kokį išlaidų ar PVM kodą priskirti P-001."],XML:["An XML document can be well-formed but still fail import because a required supplier code is absent. Validate against the receiving schema, not only whether the file opens in a browser.","XML gali būti sintaksiškai taisyklingas, bet netikti importui, nes nėra privalomo tiekėjo kodo. Tikrinkite pagal gavėjo schemą, ne vien tai, ar failas atsidaro naršyklėje."],email:["A message from supplier@example.com may contain invoices for two different organizations. The sender identifies the source; each invoice still needs its own correct organization assignment.","Laiške iš supplier@example.com gali būti dviejų organizacijų sąskaitos. Siuntėjas apibūdina šaltinį, o kiekvienai sąskaitai vis tiek reikia tinkamos organizacijos."],"google-drive":["Use a source folder such as /Invoices/Incoming and a different archive folder. A processed file remaining in the incoming folder should not be uploaded manually again without checking its record.","Naudokite šaltinio aplanką, pavyzdžiui, /Invoices/Incoming, ir kitą archyvo aplanką. Įvesties aplanke likusio apdoroto failo nekelkite ranka pakartotinai nepatikrinę jo įrašo."],sharepoint:["A site URL, a document library and a folder path are three different values. Access to the SharePoint home page does not prove access to /Shared Documents/Invoices.","Svetainės adresas, dokumentų biblioteka ir aplanko kelias – trys skirtingos reikšmės. Prieiga prie SharePoint pradžios neįrodo prieigos prie /Shared Documents/Invoices."],"fh-api":["One request identifier should refer to one intended upload. Retrying a timed-out upload without checking its result risks creating a second document. The present frontend does not provide a live API endpoint.","Vienas užklausos identifikatorius turi reikšti vieną numatytą įkėlimą. Kartojant užklausą nepatikrinus rezultato galima sukurti antrą dokumentą. Dabartinis frontend tikro API adreso nesuteikia."],dropbox:["Dropbox shown in a document Source column only describes origin. It is not evidence of an active connector. Until the connector exists, use the available manual upload without pretending a folder is being monitored.","Dropbox dokumento Šaltinio stulpelyje tik nurodo kilmę, ne veikiančią jungtį. Kol jungties nėra, naudokite esamą rankinį įkėlimą, nelaikydami aplanko automatiškai stebimu."]},f=/(?:item-codes|product-codes|service-codes|code-list|customer-list|departments|departments-objects|accountable-persons|codes-and-nomenclature|code-synchronization)$/,G=/^(?:missing-|unknown-|invalid-|wrong-|duplicate-|zero-price|number-pattern|service-unit-cost|gateway-unavailable|buyer-supplier-type|product-not-found|item-date-conflict|currencies)/,K={"gateway-api":["A configuration points to database COMPANY_A while the invoice belongs to company B. Even a valid key must not be treated as permission to post there. Correct the company / database mapping before sending; if a timeout occurred, first check whether the invoice was already received.","Nustatymuose nurodyta bazė COMPANY_A, o sąskaita priklauso įmonei B. Net galiojantis raktas nereiškia, kad ten reikia ją registruoti. Prieš siųsdami sutvarkykite įmonės ir bazės atitikmenį; jei buvo laukimo klaida, pirmiausia patikrinkite, ar sąskaita jau negauta."],warehouses:["If the receiving warehouse code is WH-01 and its name is Main warehouse, use the required identifier WH-01. A warehouse address, display name and code are not interchangeable.","Jei gavėjo sandėlio kodas WH-01, o pavadinimas Pagrindinis sandėlis, naudokite reikiamą identifikatorių WH-01. Sandėlio adresas, pavadinimas ir kodas nėra tapatūs."],"duplicate-control":["The same supplier issued AG-001 for EUR 121. Downloading that invoice twice does not create a second purchase. Compare supplier, number and amount before deciding whether another import is needed.","Tas pats tiekėjas išrašė AG-001 už 121 EUR. Dukart atsisiuntus sąskaitą neatsiranda antras pirkimas. Prieš kitą importą palyginkite tiekėją, numerį ir sumą."],"tax-codes":["The invoice shows 21% VAT, but the receiving identifier could be a configured code such as VAT_STD. Do not enter 21 instead of the code unless that is the actual receiving identifier.","Sąskaitoje nurodyta 21 % PVM, bet gavėjo identifikatorius gali būti, pavyzdžiui, VAT_STD. Vietoj kodo nerašykite 21, nebent būtent toks yra tikras gavėjo identifikatorius."],"zero-price":["A genuinely free sample has quantity 1 and price 0. Check the receiving card’s free-supply rule; changing its price to EUR 0.01 would falsify the original invoice.","Tikras nemokamas pavyzdys turi kiekį 1 ir kainą 0. Patikrinkite gavėjo kortelės nemokamo tiekimo taisyklę; pakeitus kainą į 0,01 EUR nebeatitiktų originalo."],"original-document":["Imported totals can be visible while the original-file link is unavailable. Check the file link and access separately; do not import the same accounting record again just to reopen its PDF.","Importuotos sumos gali matytis, nors originalo nuoroda neveikia. Atskirai tikrinkite failo nuorodą ir prieigą; neimportuokite apskaitos įrašo pakartotinai vien dėl PDF peržiūros."],"duplicate-counterparties":["Two cards have the same name but different codes: T-001 and company code 123456789. Compare the company identifier and existing transactions before changing the mapping; a matching name alone is insufficient.","Dviejų kortelių pavadinimas vienodas, bet kodai skiriasi: T-001 ir įmonės kodas 123456789. Prieš keisdami atitikmenį palyginkite įmonės identifikatorių ir operacijas; vien pavadinimo nepakanka."],"missing-related-data":["An address says Latvia but the receiving country directory has no LV entry. Resolve the correct country reference; replacing Latvia with Lithuania would hide the error with wrong data.","Adrese nurodyta Latvija, bet gavėjo šalių registre nėra LV. Sutvarkykite tikros šalies atitikmenį; pakeitus Latviją į Lietuvą klaida būtų paslėpta neteisingais duomenimis."],"number-pattern":["The original number is INV/2026/001 while a configured pattern allows digits only. Review the receiving pattern; do not silently turn the legal number into 2026001.","Originalo numeris INV/2026/001, o nustatytas šablonas leidžia tik skaitmenis. Tikrinkite gavėjo šabloną; nepaverskite tikro numerio į 2026001."],"missing-vat-account":["The invoice has VAT 21, but the configured input VAT GL account is absent in this company. The VAT amount is not the problem: correct the account reference.","Sąskaitoje PVM suma 21, bet nustatytos gautino PVM DK sąskaitos šios įmonės plane nėra. Problema ne PVM suma – taisykite sąskaitos atitikmenį."],"duplicate-record":["A code collision and a duplicate invoice require different corrections. If invoice P-001 is absent but item code 00 already exists, resolve the item mapping instead of renumbering P-001.","Kodų sutapimas ir sąskaitos dublikatas taisomi skirtingai. Jei P-001 nėra, bet prekės kodas 00 jau egzistuoja, taisykite prekės atitikmenį, nepernumeruokite P-001."],"missing-employee":["The integration user exists, but its linked employee code EMP-01 does not. The administrator must resolve the identity mapping; another person with a similar name is not a valid substitute.","Integracijos naudotojas yra, bet jo susieto darbuotojo kodo EMP-01 nėra. Administratorius turi sutvarkyti tapatybės atitikmenį; panašaus vardo asmuo netinka kaip pakaitalas."],"service-unit-cost":["An accounting service is assigned a Product type even though its receiving card is a service. Correct the type mapping; do not change quantity or invoice price to hide the mismatch.","Buhalterinei paslaugai priskirta Prekė, nors gavėjo kortelė yra paslauga. Taisykite tipo atitikmenį, ne kiekį ar sąskaitos kainą."],"unknown-supplier":["The XML refers to supplier T-015. Check whether that exact supplier exists and is included in the import dependencies before retrying the invoice.","XML nurodo tiekėją T-015. Prieš kartodami sąskaitą patikrinkite, ar būtent toks tiekėjas yra ir ar jo įrašas įtrauktas į importui reikalingus duomenis."],"new-customer":["A new customer has a company code but no accounting card. Search by company code first; only create a genuinely missing card through the approved receiving workflow.","Naujas klientas turi įmonės kodą, bet nėra apskaitos kortelės. Pirmiausia ieškokite pagal įmonės kodą; tikrai trūkstamą kortelę kurkite sutartu gavėjo procesu."],"operation-codes":["A purchase receipt and a sales invoice may use different operation codes. Check the code required for this direction instead of applying one default to both.","Pirkimo gavimas ir pardavimo sąskaita gali naudoti skirtingus operacijų kodus. Patikrinkite konkrečios krypties kodą, netaikykite vienos reikšmės abiem."],concepts:["A restaurant concept C-01 and warehouse WH-01 are separate references. Store each in its own field; changing the warehouse does not select the concept.","Restorano koncepcija C-01 ir sandėlis WH-01 – atskiri atitikmenys. Įrašykite juos atskiruose laukuose; pakeitus sandėlį koncepcija neparenkama."],"batch-warehouse":["One invoice contains goods for WH-01 and WH-02. A single default cannot correctly describe both destinations; check the receiving line-level allocation before applying a bulk value.","Vienoje sąskaitoje yra prekių WH-01 ir WH-02 sandėliams. Viena numatytoji reikšmė negali teisingai aprašyti abiejų; prieš masinį priskyrimą tikrinkite eilučių paskirstymą."],"product-not-found":["SKU 00015 exists in the receiving system but is excluded by a selection filter. Check both the exact code and the filter before creating a second item.","SKU 00015 gavėjo sistemoje egzistuoja, bet jį paslepia filtras. Prieš kurdami antrą prekę patikrinkite ir tikslų kodą, ir filtrą."],"expense-allocation":["The supplier product code SUP-88 can map to your expense code IT-SVC. Retain the original description while assigning the receiving accounting code.","Tiekėjo prekės kodas SUP-88 gali būti priskirtas jūsų išlaidų kodui IT-SVC. Išlaikykite originalų aprašymą, o apskaitai pasirinkite gavėjo kodą."],"products-services":["The same visible name, Delivery, may exist as both a Service and a Code. Select the matching receiving card type, not simply the first matching name.","Tas pats pavadinimas Pristatymas gali egzistuoti kaip Paslauga ir Kodas. Rinkitės gavėjo kortelės tipą, ne pirmą sutampantį pavadinimą."],"new-item-settings":["A new product uses the configured account link, whereas an existing product already has its own card settings. Do not assume changing the default rewrites every existing product.","Nauja prekė naudoja nustatytą sąskaitų ryšį, o esama jau turi savo kortelės nustatymus. Nelaikykite numatytosios reikšmės pakeitimo visų prekių perrašymu."],"automatic-export":["An invoice with a missing required department must not bypass validation merely because automatic export is enabled. Resolve the missing allocation before any real automated transmission.","Sąskaita be privalomo padalinio neturi apeiti validacijos vien dėl automatinio eksporto. Prieš tikrą automatinį perdavimą užpildykite trūkstamą paskirstymą."],"payments-persons":["An employee-paid invoice needs the correct accountable-person code and payment account. Assigning a person alone is not a bank payment or confirmation that a debt has been settled.","Darbuotojo apmokėtai sąskaitai reikia teisingo atskaitingo asmens kodo ir apmokėjimo sąskaitos. Vien asmens priskyrimas nėra banko mokėjimas ar skolos padengimo patvirtinimas."],series:["If the series is INV and number is 001, check the agreed receiving representation. Avoid producing INVINV001 by repeating the prefix in two mapped fields.","Kai serija INV, o numeris 001, patikrinkite sutartą gavėjo pateikimą. Nekartokite priešdėlio dviejuose laukuose, kad nesusidarytų INVINV001."],"missing-person":["A person named Jonas is visible in FH, but the receiving system expects code EMP-02. The name is not enough: resolve the code against the correct person card.","FH matomas Jonas, bet gavėjas tikisi kodo EMP-02. Vardo nepakanka: sutikrinkite kodą su reikiama asmens kortele."],"department-company-id":["A department was copied from company A while the integration points to B. Verify company and database identity before editing the invoice allocation.","Padalinys nukopijuotas iš įmonės A, o integracija nukreipta į B. Prieš keisdami sąskaitos paskirstymą patikrinkite įmonės ir bazės tapatybę."],"wrong-import-command":["A file ending in .xml is not an EIP file. Renaming it to .eip does not convert the schema; use the matching validated file and import action.","Failas su .xml plėtiniu nėra EIP. Pervadinus į .eip schema nepasikeičia; naudokite suderintą failą ir jam skirtą importo veiksmą."],"missing-department":["The default department code is absent from the company directory. Select an existing department matching the transaction, not an arbitrary code that merely passes validation.","Numatytojo padalinio kodo nėra įmonės registre. Rinkitės operaciją atitinkantį egzistuojantį padalinį, ne atsitiktinį kodą tik validacijai apeiti."],"invalid-quantity":["The source quantity is 1.5 but the receiving unit accepts only whole units. Review unit precision; changing the invoice quantity to 2 would alter the transaction.","Originalo kiekis 1,5, bet gavėjo vienetas priima tik sveikus kiekius. Tikrinkite vieneto tikslumą; pakeitus kiekį į 2 pasikeistų operacija."],"gateway-unavailable":["Several invoices fail with the same connection message. Check the shared connection before changing each invoice. A timeout can occur after the receiver has already created a record.","Kelios sąskaitos gauna tą pačią ryšio klaidą. Prieš taisydami kiekvieną dokumentą tikrinkite bendrą jungtį. Laukimo laikas gali baigtis ir po įrašo sukūrimo gavėjo sistemoje."],"buyer-supplier-type":["The counterparty is configured only as a buyer but the document is a purchase. Confirm the actual supplier relationship and receiving card permissions.","Kontrahentas nustatytas tik kaip pirkėjas, o dokumentas – pirkimas. Patvirtinkite tikrą tiekėjo ryšį ir gavėjo kortelės leidimus."],"change-customer-code":["Changing T-001 to T-002 must preserve links to existing documents. Confirm the receiving update procedure; creating another same-name card is not a safe code migration.","Keičiant T-001 į T-002 reikia išlaikyti ryšius su esamais dokumentais. Patvirtinkite gavėjo keitimo tvarką; kita to paties pavadinimo kortelė nėra saugus kodo perkėlimas."],"foreign-currency":["For USD 100 + USD 21 VAT, retain USD 121 as the source total. Review the accounting conversion separately; do not relabel the invoice EUR without conversion.","100 USD + 21 USD PVM sąskaitoje išlaikykite 121 USD originalo sumą. Apskaitos perskaičiavimą tikrinkite atskirai; nekeiskite valiutos į EUR be perskaičiavimo."],"code-synchronization":["A new barcode can refer to an existing product code. Verify the alternative-code mapping before creating another product; directory refresh and invoice export are different actions.","Naujas barkodas gali priklausyti esamam prekės kodui. Prieš kurdami kitą prekę patikrinkite alternatyvaus kodo atitikmenį; registro atnaujinimas ir sąskaitos eksportas – skirtingi veiksmai."]};function B(i){return i==="customer-list"?{title:["Example: counterparty import columns","Pavyzdys: kontrahento įkėlimo stulpeliai"],code:"T-001	123456789	LT123456789	Example company	",paragraphs:[["Column order: accounting code, company code, VAT code, name, IBAN. The fifth value is optional. Use real verified company identifiers, not these illustrative numbers.","Stulpelių tvarka: apskaitos kodas, įmonės kodas, PVM kodas, pavadinimas, IBAN. Penkta reikšmė neprivaloma. Naudokite tikrus patikrintus identifikatorius, ne šiuos pavyzdinius skaičius."],["Paste into Counterparties → Import from Excel, not the two-column expense importer. Check the preview for duplicate companies before saving.","Įklijuokite Kontrahentai → Įkelti iš Excel, ne į dviejų stulpelių išlaidų importą. Prieš išsaugodami peržiūroje patikrinkite pasikartojančias įmones."]]}:/departments|accountable-persons/.test(i)?{title:["Example: identifier and display name","Pavyzdys: identifikatorius ir rodomas pavadinimas"],code:i==="accountable-persons"?"EMP-01	Jonas Jonaitis":`ADMIN	Administration
SALES	Sales department`,paragraphs:[["Paste code and name into the corresponding directory. A person goes into Accountable persons, a department into Departments. Do not treat either as an expense or product code.","Kodą ir pavadinimą įklijuokite į atitinkamą registrą. Asmuo keliamas į Atskaitingus asmenis, padalinys – į Padalinius. Nei vieno nelaikykite išlaidų ar prekės kodu."]]}:N}function q(i,a){const s=f.test(a.id),o=G.test(a.id),r=K[a.id]||L[i.id];return{title:o?["Correction and result","Korekcija ir rezultatas"]:["Example and expected result","Pavyzdys ir laukiamas rezultatas"],system:"FH",example:s?B(a.id):H(U,r),steps:s?[["Open the appropriate organization directory, not a different company’s list. Verify the code in the parsed preview and save it only once.","Atverkite reikiamos organizacijos registrą, ne kitos įmonės sąrašą. Kodą patikrinkite įklijuotų duomenų peržiūroje ir išsaugokite vieną kartą."],["Open one invoice and select the imported value. Check its stored code, type and VAT mapping before assigning the same value to more documents.","Atverkite vieną sąskaitą ir pasirinkite įkeltą reikšmę. Prieš taikydami daugiau dokumentų patikrinkite išsaugotą kodą, tipą bei PVM atitikmenį."]]:o?[["Record the exact rejected document and error text. Follow the provider check above; changing unrelated invoice fields will not resolve the reported cause.","Užfiksuokite atmestą dokumentą ir tikslų klaidos tekstą. Atlikite aukščiau nurodytą konkrečios sistemos patikrinimą; kitų sąskaitos laukų keitimas priežasties neišsprendžia."],["If the source invoice was read incorrectly, send Report issue. If the source is correct, correct the receiving setting or code mapping with its administrator.","Jei sąskaitos originalas nuskaitytas neteisingai, rinkitės Pranešti apie klaidą. Jei faktai teisingi, su administratoriumi taisykite gavėjo nustatymą arba kodų atitikmenį."],["Before a real retry, search the destination by number and counterparty. Retry only the failed invoice after fixing the cause and compare the resulting amounts.","Prieš tikrą pakartojimą gavėjo sistemoje ieškokite pagal numerį ir kontrahentą. Pašalinę priežastį kartokite tik nepavykusią sąskaitą ir sutikrinkite gautas sumas."]]:[["Use one document to verify the chosen settings. Compare the original, FH fields and receiving record; a saved setting alone is not a successful transfer.","Pasirinktus nustatymus tikrinkite vienu dokumentu. Palyginkite originalą, FH laukus ir gavėjo įrašą; vien išsaugotas nustatymas nėra sėkmingas perdavimas."],[i.group==="collection"?"Expected result with a connected service: one received file, a visible source and processing status. If absent, check source permissions before uploading it again.":"Expected result with a production adapter: one invoice in the intended company, correct codes, currency and amounts. Check posting separately from receipt.",i.group==="collection"?"Laukiamas rezultatas prijungus tarnybą: vienas gautas failas su matomu šaltiniu ir apdorojimo būsena. Jei jo nėra, prieš kartodami tikrinkite šaltinio prieigos teises.":"Laukiamas rezultatas su produkciniu adapteriu: viena sąskaita reikiamoje įmonėje su teisingais kodais, valiuta ir sumomis. Perkėlimą į apskaitą tikrinkite atskirai nuo gavimo."]]}}function X(i,a){return a.map(s=>{const o=a.filter(d=>d.id!==s.id),r=o.map(d=>({topic:d.id,label:d.title})),k=(["Rivilė","Rivilė API"].includes(i.id)&&s.id==="gateway-api"?O:s.sections).map(d=>({...d}));return(i.id!=="Agnum"||s.id!=="invoice-import")&&k.push(q(i,s)),!k[0].links&&o.length&&(k[0].links=o.filter(d=>s.id==="configuration"?d.id!=="workflow-and-checks":d.id==="configuration"||f.test(d.id)).slice(0,4).map(d=>({topic:d.id,label:d.title}))),{...s,sections:k,related:r}})}const J=[z,{id:"item-codes",sourceArticleIds:[7134448],title:["Moving item codes","Prekių kodų perkėlimas"],description:["Export the code list from Agnum and add it to the organization in FH.","Kodų sąrašo eksportas iš Agnum ir įkėlimas pasirinktai FH organizacijai."],sections:[{title:["Export the list from Agnum","Sąrašo iškėlimas iš Agnum"],system:"Agnum",paragraphs:[["Using your own item identifiers for detailed invoices helps avoid duplicate item cards based on supplier codes.","Kiekinėms sąskaitoms naudojant savo prekių kodus, mažėja rizika sukurti pasikartojančias korteles pagal tiekėjų kodus."]],steps:[["Open Tools → Registers → Items. Use Operations → Data export → Excel export.","Atverkite Instrumentai → Registrai → Prekės. Pasirinkite Operacijos → Duomenų eksportas → Eksportas į Excel."],["In the spreadsheet, keep codes in column A and names in column B, then copy both columns.","Skaičiuoklėje A stulpelyje palikite kodus, B – pavadinimus ir nukopijuokite abu stulpelius."]]},{title:["Import the copied rows into FH","Nukopijuotų eilučių įkėlimas į FH"],system:"FH",steps:[["In All Documents → Documents select the organization. Open its gear → Additional columns → Expenses → Import from Excel.","Visi dokumentai → Dokumentai pasirinkite organizaciją. Atverkite jos dantratį → Papildomi stulpeliai → Išlaidos → Įkelti iš Excel."],["Choose the appropriate type: Code, Service or Product. Paste the two columns into the input. Each spreadsheet row becomes a separate code; a TAB separates its code and name.","Pasirinkite tinkamą tipą: Kodas, Paslauga arba Prekė. Į įklijavimo lauką įdėkite du stulpelius. Kiekviena skaičiuoklės eilutė tampa atskiru kodu, o kodą nuo pavadinimo skiria TAB."],["Review the parsed rows and correct reported errors before importing. Do not include a column-heading row as an item.","Peržiūrėkite atpažintas eilutes ir prieš įkeldami pataisykite nurodytas klaidas. Stulpelių antraščių eilutės neįtraukite kaip prekės."],["Import the list. To amend one code, use its Edit action; alternative codes can be added in the individual code form. The list stays with this organization.","Įkelkite sąrašą. Vienam kodui pakoreguoti naudokite jo redagavimo veiksmą; alternatyvius kodus galima nurodyti atskiro kodo formoje. Sąrašas išsaugomas šiai organizacijai."],["Return to Documents and select the saved code in Expense. Loading a code list does not itself change existing invoice allocations.","Grįžkite į Dokumentus ir lauke Išlaida pasirinkite išsaugotą kodą. Vien kodų sąrašo įkėlimas esamų sąskaitų paskirstymo nepakeičia."]]}],screenshot:{file:"expense-import.jpg",caption:["FH expense-code import: paste a code and name from Excel.","FH išlaidų kodų įkėlimas: iš Excel įklijuojamas kodas ir pavadinimas."]}},{id:"warehouses",sourceArticleIds:[6895676],title:["Assigning warehouse codes","Sandėlių kodų priskyrimas"],description:["Find the Agnum warehouse code and understand the corresponding FH settings.","Kur rasti Agnum sandėlio kodą ir kurie FH nustatymai jam skirti."],sections:[{title:["Find the warehouse in Agnum","Sandėlio paieška Agnum"],system:"Agnum",steps:[["Open Tools → Registers → Warehouses and identify the required warehouse code and description.","Atverkite Instrumentai → Registrai → Sandėliai ir raskite reikiamo sandėlio kodą bei aprašymą."],["Use that identifier, rather than an arbitrary warehouse name, when assigning a warehouse to an invoice.","Sąskaitos sandėliui priskirkite šį identifikatorių, o ne laisvai sugalvotą sandėlio pavadinimą."]]},{title:["Warehouse fields in FH","Sandėlio laukai FH"],system:"FH",steps:[["Select the organization in All Documents → Documents. In its gear open Documents & digitization setup, select Agnum and find Additional column settings.","Visi dokumentai → Dokumentai pasirinkite organizaciją. Per jos dantratį atverkite Dokumentų ir skaitmeninimo nustatymus, pasirinkite Agnum ir raskite Papildomų stulpelių nustatymus."],["Document warehouse and Line warehouse are separate fields. Their Default value cells accept the code as text; do not enter the warehouse description instead.","Dokumento sandėlis ir Eilutės sandėlis yra atskiri laukai. Jų Numatytoji reikšmė laukeliuose įrašomas tekstinis kodas, ne sandėlio aprašymas."],["Required, Assign automatically and Default value are separate choices. A saved default is configuration, not evidence that a warehouse was transferred to Agnum.","Privalomas, Priskirti automatiškai ir Numatytoji reikšmė yra atskiros parinktys. Išsaugota numatytoji reikšmė yra nustatymas, ne įrodymas, kad sandėlis jau perduotas į Agnum."]]}],note:["This FH gear menu does not yet have a separate warehouse-code directory or an Agnum warehouse picker for each document. The available fields are export settings; the full per-document warehouse workflow is not implemented here.","Šiame FH dantračio meniu dar nėra atskiro sandėlių kodų registro ir Agnum sandėlio pasirinkimo kiekviename dokumente. Esami laukai yra eksporto nustatymai; visas sandėlio priskyrimo dokumentui procesas čia dar neįgyvendintas."]},{id:"duplicate-control",sourceArticleIds:[4107703],title:["Duplicate control","Dublikatų kontrolė"],description:["Enable checks in Agnum and distinguish them from OCR duplicate warnings.","Dublikatų tikrinimas Agnum ir jo skirtumas nuo OCR įspėjimų."],sections:[{title:["Enable the checks in Agnum","Tikrinimo įjungimas Agnum"],system:"Agnum",steps:[["Open Tools → Parameters, then the Documents section.","Atverkite Instrumentai → Parametrai, tada Dokumentai skiltį."],["Under Purchases 1 enable the control that prevents repeating an invoice number for the same supplier.","Skiltyje Pirkimai 1 įjunkite tikrinimą, neleidžiantį kartoti dokumento numerio tam pačiam tiekėjui."],["Under Sales 1 enable immediate document-number checking.","Skiltyje Pardavimai 1 įjunkite dokumento numerio tikrinimą iš karto."]]},{title:["What this means in FH","Ką tai reiškia FH"],system:"FH",paragraphs:[["An OCR duplicate warning and the receiving accounting system’s duplicate control are different checks. This help page does not change any Agnum settings.","OCR įspėjimas apie dublikatą ir apskaitos sistemos dublikatų kontrolė yra skirtingi tikrinimai. Šis pagalbos puslapis nekeičia jokių Agnum nustatymų."],["In All Documents → Uploaded documents, click the Duplicate status to review its details. If View original is available, open the referenced document and compare it before proceeding.","Visi dokumentai → Įkelti dokumentai paspauskite būseną Dublikatas ir peržiūrėkite paaiškinimą. Jei yra Peržiūrėti originalą nuoroda, atverkite susietą dokumentą ir palyginkite prieš tęsdami."],["A file downloaded again is still the same invoice, not a new one. Before a real retry, check the destination-system result; FH export or archive state alone cannot prove whether Agnum created the document.","Pakartotinai atsisiųstas failas vis tiek yra ta pati sąskaita, ne nauja. Prieš realų pakartotinį importą patikrinkite gavėjo sistemos rezultatą; vien FH eksporto ar archyvo būsena neįrodo, ar Agnum sukūrė dokumentą."]]}]}],_=Object.fromEntries(c.map(i=>[i.id,R[i.id]||X(i,[...V(i),...i.id==="Agnum"?J:u[i.id]||[]])])),W=i=>_[i]||[],ii=(i,a)=>W(i).find(s=>s.id===a);export{c as I,W as a,ii as b,Y as i};
